import { extendComplex, COMPLEX_LESSONS, type ComplexCourseKind } from './complex-course-topics'
import { extendGeometry, GEOMETRY_LESSONS, type GeometrySlideKind } from './geometry-slide-topics'
import { extendAlgebra, SLIDE_LESSONS, type AlgebraSlideKind } from './algebra-slide-topics'
import type { Bilingual } from './summary-examples'

export type VisualKind = 'triangle' | 'polar' | 'roots' | 'disc' | 'map' | 'derivative' | 'cr' | 'harmonic' | 'exp' | 'branch' | 'trig' | 'integral' | 'primitive' | 'cauchy' | 'series' | 'singularities' | 'residue' | 'basis' | 'products' | 'plane' | 'projection' | 'power' | 'radical' | 'conic' | 'quadric' | 'eigen' | 'reduce' | 'affine' | 'isometry' | 'group' | 'cyclic' | 'cosets' | 'kernel' | 'quotient' | 'cycles' | 'parity' | 'ring' | 'ideal' | 'division' | 'eisenstein' | AlgebraSlideKind | GeometrySlideKind | ComplexCourseKind
export type DerivationStep = { title: Bilingual; text: Bilingual; tex: string }
export type SummaryLesson = {
  visual: VisualKind
  question: Bilingual
  steps: DerivationStep[]
  conditions: Bilingual[]
  failure: Bilingual
  exampleSteps: DerivationStep[]
  check: { question: Bilingual; answer: Bilingual }
}
const b = (id: string, en: string): Bilingual => ({ id, en })
const s = (titleId: string, titleEn: string, id: string, en: string, tex: string): DerivationStep => ({ title: b(titleId, titleEn), text: b(id, en), tex })
const l = (visual: VisualKind, question: Bilingual, steps: DerivationStep[], conditions: Bilingual[], failure: Bilingual, exampleSteps: DerivationStep[], checkQuestion: Bilingual, checkAnswer: Bilingual): SummaryLesson => ({ visual, question, steps, conditions, failure, exampleSteps, check: { question: checkQuestion, answer: checkAnswer } })

/** The array order follows SUMMARY: course → subsection → topic. */
export const SUMMARY_LESSONS: Record<string, SummaryLesson[][]> = {
  complex: [
    [
      l('triangle', b('Mengapa modulus memakai akar, dan mengapa konjugat membantu pembagian?', 'Why does the modulus use a square root, and why does the conjugate help division?'), [
        s('Mulai dari titik', 'Start with a point', 'z = x + iy berarti titik (x,y). Garis mendatar dan tegak membentuk segitiga siku-siku; jarak dari asal adalah sisi miringnya.', 'z = x + iy means the point (x,y). Horizontal and vertical legs form a right triangle; its hypotenuse is the distance from the origin.', String.raw`|z|^2=x^2+y^2`),
        s('Cerminkan lalu kalikan', 'Reflect, then multiply', 'Konjugat membalik tanda y. Saat kedua faktor dikalikan, suku silang saling menghapus dan i² = −1 mengubah −i²y² menjadi +y².', 'The conjugate reverses y. Multiplication cancels the cross terms, and i² = −1 turns −i²y² into +y².', String.raw`(x+iy)(x-iy)=x^2+y^2`),
        s('Buat penyebut real', 'Make the denominator real', 'Kalikan pembilang dan penyebut dengan konjugat penyebut. Ini mengalikan pecahan dengan 1, sehingga nilainya tetap, tetapi penyebut menjadi kuadrat jarak.', 'Multiply numerator and denominator by the denominator’s conjugate. This multiplies the fraction by 1, preserving its value while turning the denominator into a squared distance.', String.raw`\frac{z_1}{z_2}=\frac{z_1\bar z_2}{z_2\bar z_2}=\frac{z_1\bar z_2}{|z_2|^2}`),
      ], [b('Pembagian memerlukan z₂ ≠ 0. Modulus selalu real dan tidak negatif.', 'Division requires z₂ ≠ 0. The modulus is always real and nonnegative.')], b('Di z₂ = 0, penyebut |z₂|² juga nol; konjugat tidak menyelesaikan pembagian dengan nol.', 'At z₂ = 0, |z₂|² is also zero; conjugation cannot fix division by zero.'), [
        s('Ukur dua sisi', 'Measure the legs', 'Untuk 3 + 4i, sisi segitiga adalah 3 dan 4. Kuadrat jaraknya 9 + 16.', 'For 3 + 4i, the triangle’s legs are 3 and 4. The squared distance is 9 + 16.', String.raw`|3+4i|=\sqrt{9+16}=5`),
        s('Periksa dengan perkalian', 'Check by multiplication', 'Cermin titiknya adalah 3 − 4i. Hasil kalinya 25, sama dengan 5².', 'Its reflected point is 3 − 4i. Their product is 25, equal to 5².', String.raw`(3+4i)(3-4i)=9-16i^2=25`),
      ], b('Apakah |3 + 4i| = 3 + 4?', 'Is |3 + 4i| equal to 3 + 4?'), b('Tidak. 3 + 4 adalah panjang perjalanan lewat dua sisi; modulus adalah jarak lurus, yaitu 5.', 'No. 3 + 4 is the journey along both legs; the modulus is the straight distance, 5.')),
      l('polar', b('Mengapa perkalian kompleks menjumlahkan sudut?', 'Why does complex multiplication add angles?'), [
        s('Ubah posisi menjadi panjang dan arah', 'Replace position with length and direction', 'Titik pada lingkaran satuan memiliki koordinat (cos θ, sin θ). Mengalikan keduanya dengan r memberi titik pada jarak r.', 'A point on the unit circle has coordinates (cos θ, sin θ). Multiplying both by r places it at distance r.', String.raw`z=r(\cos\theta+i\sin\theta)=re^{i\theta}`),
        s('Kalikan dua arah', 'Multiply two directions', 'Kembangkan perkalian dan gunakan rumus penjumlahan sinus-kosinus. Komponen real menjadi cos(α+β), komponen imajiner menjadi sin(α+β).', 'Expand the product and use the sine and cosine addition identities. The real component becomes cos(α+β), and the imaginary component becomes sin(α+β).', String.raw`r_1e^{i\alpha}r_2e^{i\beta}=r_1r_2e^{i(\alpha+\beta)}`),
        s('Ulangi perkalian', 'Repeat the multiplication', 'Pangkat bulat positif berarti mengalikan arah yang sama n kali. Panjang dikalikan berulang dan sudut ditambah berulang; itulah de Moivre.', 'A positive integer power repeats the same multiplication n times. Length multiplies repeatedly and angle adds repeatedly; this gives de Moivre’s formula.', String.raw`(re^{i\theta})^n=r^ne^{in\theta}`),
      ], [b('Argumen hanya terdefinisi untuk z ≠ 0. Sudut yang berbeda 2π menunjuk titik yang sama.', 'The argument is defined only for z ≠ 0. Angles differing by 2π describe the same point.'), b('de Moivre dalam bentuk ini memakai pangkat bulat; pangkat negatif juga memerlukan z ≠ 0.', 'This form of de Moivre uses integer powers; negative powers also require z ≠ 0.')], b('Arg utama harus dikembalikan ke interval (−π, π]. Jumlah dua Arg utama bisa keluar dari interval itu.', 'The principal Arg must be brought back into (−π, π]. Adding two principal arguments can leave this interval.'), [
        s('Baca panjang dan sudut', 'Read length and angle', '1+i memiliki panjang √2 dan sudut π/4.', '1+i has length √2 and angle π/4.', String.raw`1+i=\sqrt2e^{i\pi/4}`),
        s('Pangkatkan keduanya', 'Raise both parts', 'Empat perkalian memberi panjang (√2)⁴ = 4 dan sudut 4π/4 = π, yaitu titik −4.', 'Four multiplications give length (√2)⁴ = 4 and angle 4π/4 = π, placing the result at −4.', String.raw`(1+i)^4=4e^{i\pi}=-4`),
      ], b('Apa yang dilakukan perkalian dengan i?', 'What does multiplication by i do?'), b('i memiliki panjang 1 dan sudut π/2, jadi panjang tetap dan arah berputar 90° berlawanan jarum jam.', 'i has length 1 and angle π/2, so length stays fixed and direction rotates 90° counterclockwise.')),
      l('roots', b('Dari mana n jawaban akar pangkat n berasal?', 'Where do the n answers to an nth root come from?'), [
        s('Tulis target dalam bentuk kutub', 'Write the target in polar form', 'Misalkan wⁿ = r₀e^{iθ₀}. Pangkat mengubah panjang menjadi rⁿ dan sudut menjadi nθ.', 'Suppose wⁿ = r₀e^{iθ₀}. The power turns length into rⁿ and angle into nθ.', String.raw`w=re^{i\theta}\implies w^n=r^ne^{in\theta}`),
        s('Balikkan panjang dan sudut', 'Undo length and angle', 'Panjang harus memenuhi rⁿ = r₀. Untuk arah, semua θ₀ + 2πk sama-sama menunjuk target, sehingga semuanya harus dipertimbangkan sebelum dibagi n.', 'Length must satisfy rⁿ = r₀. Every θ₀ + 2πk points to the same target, so consider all of them before dividing by n.', String.raw`r=r_0^{1/n},\qquad \theta=\frac{\theta_0+2\pi k}{n}`),
        s('Ambil jawaban yang berbeda', 'Keep the distinct answers', 'k = 0 sampai n−1 menghasilkan n titik dengan sela sudut 2π/n. k = n kembali ke titik pertama; karena itu tidak memberi jawaban baru.', 'k = 0 through n−1 produces n points spaced by 2π/n. k = n returns to the first point, so it adds no new answer.', String.raw`w_k=r_0^{1/n}e^{i(\theta_0+2\pi k)/n},\quad k=0,\ldots,n-1`),
      ], [b('n adalah bilangan bulat positif. Untuk target bukan nol, ada n akar yang berbeda.', 'n is a positive integer. A nonzero target has n distinct roots.')], b('Jika targetnya nol, semua bentuk di atas runtuh ke satu titik: w = 0, bukan n akar berbeda.', 'If the target is zero, the construction collapses to one point: w = 0, not n distinct roots.'), [
        s('Targetnya 1', 'The target is 1', '1 memiliki radius 1 dan argumen 0. Bagilah sudut 0, 2π, 4π dengan 3.', '1 has radius 1 and argument 0. Divide the angles 0, 2π, 4π by 3.', String.raw`\theta_k=0,\frac{2\pi}{3},\frac{4\pi}{3}`),
        s('Periksa hasil', 'Check the roots', 'Ketiga titik diputar tiga kali sudutnya oleh pangkat tiga; semuanya kembali ke 1.', 'Cubing triples each point’s angle; all three return to 1.', String.raw`1^3=(e^{2\pi i/3})^3=(e^{4\pi i/3})^3=1`),
      ], b('Mengapa mengambil k = 3 tidak menambah akar kubik baru?', 'Why does k = 3 add no new cube root?'), b('Sudutnya 2π, yang sama dengan sudut 0. Titiknya kembali ke 1.', 'Its angle is 2π, equivalent to 0. The point returns to 1.')),
      l('disc', b('Apa sebenarnya arti terbuka, batas, dan daerah?', 'What do open, boundary, and domain actually mean?'), [
        s('Uji dengan lingkaran kecil', 'Test with a small disc', 'Titik interior punya ruang bergerak: ada radius ε > 0 sehingga seluruh cakram kecil di sekitarnya tetap berada di himpunan.', 'An interior point has room to move: some radius ε > 0 keeps its entire small disc inside the set.', String.raw`D_\varepsilon(z)=\{w:|w-z|<\varepsilon\}`),
        s('Lihat titik yang menyentuh dua sisi', 'Look at points touching both sides', 'Pada batas, sekecil apa pun cakram yang dipilih, cakram itu menyentuh himpunan dan komplemennya. Batas tidak ditentukan oleh apakah titiknya ikut dimasukkan.', 'At a boundary point, every small disc meets both the set and its complement. Boundary status does not depend on whether the point itself is included.', String.raw`\partial\{|z|<1\}=\{|z|=1\}`),
        s('Tambahkan keterhubungan', 'Add connectedness', 'Terbuka berarti semua titiknya interior. Daerah atau domain berarti terbuka dan terhubung: tidak terpisah menjadi dua bagian terbuka yang tidak saling bertemu.', 'Open means every point is interior. A domain is open and connected: it does not split into two disjoint nonempty open pieces.', String.raw`\text{domain}=\text{open}+\text{connected}`),
      ], [b('Analitik pada suatu daerah berarti punya turunan pada setiap titik daerah terbuka itu.', 'Analytic on a domain means differentiable at every point of that open domain.')], b('Himpunan |z| ≤ 1 bukan terbuka: di titik lingkaran, setiap cakram kecil keluar dari himpunan.', 'The set |z| ≤ 1 is not open: at a circle point, every small disc extends outside it.'), [
        s('Ambil titik interior', 'Choose an interior point', 'Di z = 0.6, jarak ke lingkaran satuan adalah 0.4. Cakram radius 0.2 pasti masih di dalamnya.', 'At z = 0.6, the distance to the unit circle is 0.4. A disc of radius 0.2 stays inside.', String.raw`|w-0.6|<0.2\implies |w|<0.8<1`),
        s('Uji batas', 'Test the boundary', 'Di z = 1, setiap ε mencakup titik 1 + ε/2 di luar cakram satuan.', 'At z = 1, every ε includes the point 1 + ε/2 outside the unit disc.', String.raw`|1+\varepsilon/2|>1`),
      ], b('Apakah dua cakram terpisah membentuk satu domain?', 'Do two separated discs form one domain?'), b('Tidak. Gabungannya terbuka tetapi tidak terhubung.', 'No. Their union is open but disconnected.')),
    ],
    [
      l('map', b('Bagaimana rumus berubah menjadi pemetaan dua bidang?', 'How does a formula become a map between two planes?'), [
        s('Pisahkan masukan', 'Split the input', 'Satu bilangan z membawa dua koordinat x dan y. Untuk mengetahui tujuan titiknya, masukkan x+iy ke fungsi.', 'One number z carries two coordinates x and y. To locate its destination, substitute x+iy into the function.', String.raw`z=x+iy,\qquad f(z)=u(x,y)+iv(x,y)`),
        s('Kumpulkan real dan imajiner', 'Collect real and imaginary terms', 'Untuk z², i² = −1 menghasilkan u = x²−y² dan v = 2xy. Kedua fungsi real ini menentukan posisi pada bidang keluaran.', 'For z², i² = −1 gives u = x²−y² and v = 2xy. These two real functions locate the point in the output plane.', String.raw`(x+iy)^2=(x^2-y^2)+i(2xy)`),
        s('Petakan seluruh kurva', 'Map the whole curve', 'Garis x = c bukan satu titik. Biarkan y bergerak, hitung semua pasangan (u,v), lalu hubungkan hasilnya. Inilah asal kurva bayangan dalam visual.', 'The line x = c is not one point. Let y vary, compute each (u,v), and connect the results. This produces the image curve in the visual.', String.raw`x=c:\quad (u,v)=(c^2-y^2,2cy)`),
      ], [b('Fungsi harus terdefinisi pada setiap titik masukan yang dipetakan.', 'The function must be defined at every input being mapped.'), b('Eliminasi y = v/(2c) memerlukan c ≠ 0; jika c = 0, langsung gunakan v = 0 dan u = −y².', 'Eliminating y = v/(2c) requires c ≠ 0; at c = 0, use v = 0 and u = −y² directly.')], b('Pemetaan tidak harus satu-ke-satu. Untuk z², z dan −z punya bayangan yang sama.', 'A map need not be one-to-one. Under z², z and −z have the same image.'), [
        s('Masukkan koordinat', 'Insert the coordinates', 'Pada titik 1+i, x = y = 1.', 'At 1+i, x = y = 1.', String.raw`u=1^2-1^2=0,\quad v=2(1)(1)=2`),
        s('Baca posisi baru', 'Read the new position', 'Koordinat (0,2) berarti 2i. Panjang awal √2 menjadi 2; sudut π/4 menjadi π/2.', 'Coordinates (0,2) mean 2i. The original length √2 becomes 2; the angle π/4 becomes π/2.', String.raw`f(1+i)=2i`),
      ], b('Apakah garis lurus selalu tetap lurus?', 'Does a straight line always stay straight?'), b('Tidak. Pada z², garis x = 1 menjadi parabola u = 1 − v²/4.', 'No. Under z², the line x = 1 becomes the parabola u = 1 − v²/4.')),
      l('derivative', b('Mengapa turunan kompleks menjelaskan skala dan rotasi?', 'Why does a complex derivative describe scale and rotation?'), [
        s('Ukur perubahan kecil', 'Measure a small change', 'Ambil perpindahan kecil h dari z₀. Rasio perubahan keluaran terhadap h mengukur respons fungsi, bukan sekadar beda dua nilai.', 'Take a small displacement h from z₀. Dividing the output change by h measures the function’s response, rather than merely subtracting two values.', String.raw`\frac{f(z_0+h)-f(z_0)}{h}`),
        s('Dekati dari setiap arah', 'Approach from every direction', 'h dapat datang dari arah real, imajiner, atau arah lain. Turunan ada hanya bila semua pendekatan menghasilkan limit yang sama.', 'h may approach along the real axis, imaginary axis, or any other direction. The derivative exists only if all approaches give the same limit.', String.raw`f'(z_0)=\lim_{h\to0}\frac{f(z_0+h)-f(z_0)}h`),
        s('Baca perkalian lokal', 'Read the local multiplication', 'Untuk h sangat kecil, perubahan keluaran mendekati f′(z₀)h. Perkalian kompleks mengalikan panjang dengan |f′| dan menambah sudut arg f′.', 'For very small h, the output change is approximately f′(z₀)h. Complex multiplication scales length by |f′| and rotates by arg f′.', String.raw`f(z_0+h)=f(z_0)+f'(z_0)h+o(|h|)`),
      ], [b('Limit harus sama untuk semua arah, bukan hanya dua arah yang diuji.', 'The limit must agree along every direction, not just two tested directions.'), b('Makna rotasi dan pelestarian sudut lokal memerlukan f′(z₀) ≠ 0.', 'The rotation and local angle-preservation interpretation requires f′(z₀) ≠ 0.')], b('Untuk f(z) = konjugat z, rasio adalah 1 sepanjang h real dan −1 sepanjang h imajiner; turunan kompleks tidak ada.', 'For f(z) = conjugate z, the ratio is 1 along real h and −1 along imaginary h; no complex derivative exists.'), [
        s('Kembangkan selisih', 'Expand the difference', 'Untuk z², pembilang adalah 2z₀h + h². Setelah dibagi h, tersisa 2z₀+h.', 'For z², the numerator is 2z₀h+h². Dividing by h leaves 2z₀+h.', String.raw`\frac{(z_0+h)^2-z_0^2}h=2z_0+h\to2z_0`),
        s('Baca geometri turunan', 'Read its geometry', 'Di 1+i, turunan 2+2i memperbesar perpindahan kecil sebesar 2√2 dan memutarnya π/4.', 'At 1+i, the derivative 2+2i scales small displacements by 2√2 and rotates them by π/4.', String.raw`f'(1+i)=2+2i=2\sqrt2e^{i\pi/4}`),
      ], b('Jika dua arah memberi limit berbeda, perlu menguji arah lainnya?', 'If two directions give different limits, must you test more?'), b('Tidak. Dua limit berbeda sudah membuktikan bahwa satu limit bersama tidak ada.', 'No. Two different limits already disprove the existence of a common limit.')),
      l('cr', b('Dari mana persamaan Cauchy–Riemann berasal?', 'Where do the Cauchy–Riemann equations come from?'), [
        s('Datang dari arah mendatar', 'Approach horizontally', 'Tulis f = u+iv. Jika h real, rasio selisih menuju uₓ+ivₓ, karena hanya x yang berubah.', 'Write f = u+iv. For real h, the difference quotient tends to uₓ+ivₓ because only x changes.', String.raw`h\in\mathbb R:\quad f'=u_x+iv_x`),
        s('Datang dari arah tegak', 'Approach vertically', 'Gunakan h = it. Pembilang mendekati t(uᵧ+ivᵧ). Membagi dengan it memberi vᵧ−iuᵧ, sebab 1/i = −i.', 'Use h = it. The numerator approaches t(uᵧ+ivᵧ). Dividing by it gives vᵧ−iuᵧ because 1/i = −i.', String.raw`h=it:\quad f'=\frac{u_y+iv_y}{i}=v_y-iu_y`),
        s('Samakan dua jawaban', 'Match the two answers', 'Satu turunan harus memberi jawaban sama dari kedua arah. Samakan bagian real dan imajiner; diperoleh dua persamaan CR.', 'One derivative must give the same answer from both directions. Equating the real and imaginary parts gives the two CR equations.', String.raw`u_x=v_y,\qquad u_y=-v_x`),
      ], [b('CR perlu jika turunan kompleks ada. Sebagai syarat cukup, gunakan u,v dengan turunan parsial kontinu di lingkungan titik dan CR di titik itu.', 'CR is necessary when the complex derivative exists. For sufficiency, use u,v with continuous first partial derivatives near the point and CR at that point.'), b('Untuk menyimpulkan analitik pada daerah, syarat tersebut harus berlaku pada setiap titik daerah.', 'To conclude analyticity on a domain, those conditions must hold at every point in the domain.')], b('CR pada satu titik saja, tanpa regularitas yang cukup, tidak menjamin turunan; dan turunan pada satu titik tidak berarti analitik di sekitarnya.', 'CR at one point alone, without sufficient regularity, does not guarantee differentiability; differentiability at one point does not imply analyticity nearby.'), [
        s('Hitung empat turunan', 'Compute the four partials', 'Untuk z², gunakan u = x²−y² dan v = 2xy.', 'For z², use u = x²−y² and v = 2xy.', String.raw`u_x=2x,\ u_y=-2y,\ v_x=2y,\ v_y=2x`),
        s('Periksa syarat cukup', 'Check sufficiency', 'Keempat parsial kontinu dan CR cocok di seluruh bidang; karena itu z² analitik di seluruh C.', 'All four partials are continuous and CR agrees everywhere, so z² is analytic throughout C.', String.raw`2x=2x,\qquad -2y=-2y`),
      ], b('Mengapa tanda minus pada persamaan kedua diperlukan?', 'Why is the minus sign in the second equation needed?'), b('Karena perpindahan tegak dibagi dengan i, dan 1/i = −i. Tanda minus muncul dari pembagian ini.', 'Because a vertical displacement is divided by i, and 1/i = −i. That division produces the minus sign.')),
      l('harmonic', b('Mengapa bagian real fungsi analitik memenuhi persamaan Laplace?', 'Why does the real part of an analytic function satisfy Laplace’s equation?'), [
        s('Mulai dari CR', 'Start with CR', 'Analitik mengikat u dan v melalui CR. Turunkan persamaan pertama terhadap x dan persamaan kedua terhadap y.', 'Analyticity links u and v through CR. Differentiate the first equation with respect to x and the second with respect to y.', String.raw`u_{xx}=v_{yx},\qquad u_{yy}=-v_{xy}`),
        s('Jumlahkan kelengkungan', 'Add the curvatures', 'Turunan campuran sama untuk fungsi cukup mulus. Karena tandanya berlawanan, dua suku itu menghapus: kelengkungan x dan y berjumlah nol.', 'Mixed partials agree for sufficiently smooth functions. Their opposite signs cancel: curvature in x and y sums to zero.', String.raw`\Delta u=u_{xx}+u_{yy}=v_{yx}-v_{xy}=0`),
        s('Cari pasangan harmonik', 'Find a harmonic partner', 'Untuk membangun v dari u, CR menentukan vₓ dan vᵧ. Integralkan salah satunya lalu gunakan yang lain untuk menentukan fungsi tambahan.', 'To construct v from u, CR determines vₓ and vᵧ. Integrate one, then use the other to determine the extra function.', String.raw`v_y=u_x,\qquad v_x=-u_y`),
      ], [b('Harmonik berarti punya parsial kedua kontinu dan Δu = 0 pada daerah terbuka.', 'Harmonic means continuous second partials and Δu = 0 on an open domain.'), b('Pasangan harmonik selalu ada secara lokal; daerah terhubung sederhana menjamin pasangan global. Pasangan berbeda hanya sebesar konstanta pada daerah terhubung.', 'A harmonic conjugate exists locally; a simply connected domain guarantees a global one. On a connected domain, conjugates differ only by a constant.')], b('u = log|z| harmonik di C tanpa nol, tetapi arg z tidak dapat dipilih kontinu secara global di daerah berlubang itu.', 'u = log|z| is harmonic on C without zero, but arg z cannot be chosen globally continuous on that punctured domain.'), [
        s('Periksa Laplace', 'Check Laplace', 'Untuk u = x²−y², kelengkungan x adalah 2 dan kelengkungan y adalah −2.', 'For u = x²−y², x-curvature is 2 and y-curvature is −2.', String.raw`\Delta u=2-2=0`),
        s('Bangun v', 'Construct v', 'vᵧ = 2x memberi v = 2xy+g(x). Persamaan vₓ = 2y memaksa g′ = 0.', 'vᵧ = 2x gives v = 2xy+g(x). The equation vₓ = 2y forces g′ = 0.', String.raw`v=2xy+C,\qquad u+iv=z^2+iC`),
      ], b('Apakah harmonik berarti fungsi realnya selalu datar?', 'Does harmonic mean the real function is always flat?'), b('Tidak. x²−y² berbentuk pelana: kelengkungan dua arah saling mengimbangi.', 'No. x²−y² is a saddle: the curvatures in two directions balance.')),
    ],
    [
      l('exp', b('Mengapa e^(x+iy) punya radius eˣ dan sudut y?', 'Why does e^(x+iy) have radius eˣ and angle y?'), [
        s('Pisahkan dua bagian', 'Separate the two parts', 'Hukum eksponensial memisahkan penjumlahan menjadi perkalian: e^(x+iy) = eˣeⁱʸ.', 'The exponential law turns addition into multiplication: e^(x+iy) = eˣeⁱʸ.', String.raw`e^{x+iy}=e^xe^{iy}`),
        s('Baca lingkaran satuan', 'Read the unit circle', 'Rumus Euler menempatkan eⁱʸ pada lingkaran satuan. y menentukan arah, sementara eˣ mengubah radius.', 'Euler’s formula places eⁱʸ on the unit circle. y sets the direction, while eˣ changes the radius.', String.raw`e^{x+iy}=e^x(\cos y+i\sin y)`),
        s('Ikuti garis masukan', 'Follow input lines', 'Garis x konstan dipetakan ke lingkaran beradius eˣ. Garis y konstan dipetakan ke sinar bersudut y. Karena eˣ > 0, keluaran tidak pernah nol.', 'A constant-x line maps to a circle of radius eˣ. A constant-y line maps to a ray at angle y. Since eˣ > 0, the output is never zero.', String.raw`|e^z|=e^x,\quad e^{z+2\pi i}=e^z`),
      ], [b('Eksponensial terdefinisi dan analitik pada seluruh C, tetapi tidak satu-ke-satu.', 'The exponential is defined and analytic on all of C, but is not one-to-one.')], b('y dan y+2π memberi keluaran sama. Membalik eksponensial memerlukan pilihan cabang logaritma.', 'y and y+2π give the same output. Inverting the exponential requires a logarithm branch.'), [
        s('Setel koordinat', 'Set the coordinates', 'Untuk iπ, x = 0 dan y = π, jadi radiusnya e⁰ = 1.', 'For iπ, x = 0 and y = π, so the radius is e⁰ = 1.', String.raw`e^{i\pi}=1(\cos\pi+i\sin\pi)`),
        s('Baca arah', 'Read the direction', 'Sudut π menunjuk ke kiri pada sumbu real: hasilnya −1.', 'Angle π points left along the real axis: the result is −1.', String.raw`e^{i\pi}=-1`),
      ], b('Bisakah eᶻ = 0 untuk suatu z?', 'Can eᶻ = 0 for some z?'), b('Tidak. Modulusnya eˣ selalu positif untuk setiap x hingga.', 'No. Its modulus eˣ is positive for every finite x.')),
      l('branch', b('Mengapa logaritma kompleks membutuhkan potongan cabang?', 'Why does a complex logarithm need a branch cut?'), [
        s('Balikkan eksponensial', 'Invert the exponential', 'Jika eʷ = z dan z = reⁱθ, maka bagian real w adalah ln r. Bagian imajiner bisa θ+2πk karena semua arah itu sama.', 'If eʷ = z and z = reⁱθ, the real part of w is ln r. Its imaginary part may be θ+2πk because all those angles coincide.', String.raw`\log z=\ln|z|+i(\theta+2\pi k)`),
        s('Pilih satu rentang sudut', 'Choose one angle range', 'Untuk memperoleh satu nilai, pilih sudut secara kontinu. Cabang utama memakai −π < arg z < π pada bidang tanpa sumbu real negatif dan nol.', 'To obtain a single value, choose the angle continuously. The principal analytic branch uses −π < arg z < π on the plane without the nonpositive real axis.', String.raw`\operatorname{Log}z=\ln|z|+i\operatorname{Arg}z`),
        s('Lihat lompatan di potongan', 'See the jump at the cut', 'Mendekati −1 dari atas memberi sudut mendekati π; dari bawah memberi −π. Nilai batas berbeda 2πi, sehingga satu cabang tidak analitik melintasi potongan.', 'Approaching −1 from above gives angle π; from below gives −π. The boundary values differ by 2πi, so one branch cannot be analytic across the cut.', String.raw`\operatorname{Log}(-1\pm i0)=\pm i\pi`),
      ], [b('z ≠ 0. Cabang log harus dinyatakan pada daerah yang memungkinkan argumen kontinu; pada daerah terhubung sederhana tanpa nol, cabang ada.', 'z ≠ 0. State the branch on a domain allowing a continuous argument; a simply connected domain avoiding zero admits one.'), b('Nilai utama dapat diberi nilai di sisi potongan secara konvensi, tetapi cabang analitik utamanya mengecualikan potongan.', 'A principal value may be assigned on a cut by convention, but the principal analytic branch excludes the cut.')], b('Log(ab) = Log a + Log b tidak selalu benar untuk nilai utama; sudut bisa melewati rentang pilihan.', 'Log(ab) = Log a + Log b may fail for principal values; the angle can cross the chosen range.'), [
        s('Dekati dari atas', 'Approach from above', 'Modulus menuju 1 dan argumen menuju π.', 'The modulus tends to 1 and the argument tends to π.', String.raw`\lim_{\varepsilon\downarrow0}\operatorname{Log}(-1+i\varepsilon)=i\pi`),
        s('Dekati dari bawah', 'Approach from below', 'Modulus sama, tetapi argumen menuju −π. Perbedaannya berasal dari pilihan sudut, bukan jarak.', 'The modulus is the same, but the argument tends to −π. The difference comes from the angle choice, not the distance.', String.raw`\lim_{\varepsilon\downarrow0}\operatorname{Log}(-1-i\varepsilon)=-i\pi`),
      ], b('Apakah potongan cabang berarti fungsi asal rusak di setiap titik potongan?', 'Does a branch cut mean every cut point is intrinsically singular?'), b('Tidak. Di sekitar −1 dapat dipilih cabang lain. Potongan membantu membuat satu pilihan sudut yang konsisten secara global.', 'No. Another branch can be chosen near −1. The cut makes a particular global angle choice consistent.')),
      l('trig', b('Mengapa sinus masukan imajiner berubah menjadi sinus hiperbolik?', 'Why does sine of an imaginary input become hyperbolic sine?'), [
        s('Bangun dari eksponensial', 'Build from exponentials', 'Untuk masukan real, rumus Euler memberi jumlah dan selisih eⁱᶻ serta e⁻ⁱᶻ. Rumus ini juga mendefinisikan sinus-kosinus pada masukan kompleks.', 'For real inputs, Euler’s formula gives sums and differences of eⁱᶻ and e⁻ⁱᶻ. These formulas also define sine and cosine for complex inputs.', String.raw`\sin z=\frac{e^{iz}-e^{-iz}}{2i},\quad \cos z=\frac{e^{iz}+e^{-iz}}2`),
        s('Masukkan z = iy', 'Substitute z = iy', 'Karena i·iy = −y, eksponen yang tadinya imajiner menjadi real. Ini menghasilkan eʸ dan e⁻ʸ, bukan rotasi pada lingkaran.', 'Since i·iy = −y, the exponents become real. This produces eʸ and e⁻ʸ rather than rotations on a circle.', String.raw`\sin(iy)=\frac{e^{-y}-e^y}{2i}`),
        s('Kenali fungsi hiperbolik', 'Recognize the hyperbolic functions', 'sinh y adalah setengah selisih eʸ dan e⁻ʸ; cosh y adalah setengah jumlahnya. Membagi dengan i menghasilkan faktor i pada sinus.', 'sinh y is half the difference of eʸ and e⁻ʸ; cosh y is half their sum. Dividing by i produces the factor i in sine.', String.raw`\sin(iy)=i\sinh y,\qquad \cos(iy)=\cosh y`),
      ], [b('Sinus dan kosinus analitik pada seluruh C. Batas −1 sampai 1 hanya berlaku pada masukan real.', 'Sine and cosine are analytic on all of C. The bounds −1 to 1 apply only to real inputs.')], b('Jangan menganggap |sin z| ≤ 1 untuk z kompleks; sinh y tumbuh tanpa batas.', 'Do not assume |sin z| ≤ 1 for complex z; sinh y grows without bound.'), [
        s('Ganti z dengan i', 'Replace z with i', 'Gunakan y = 1, sehingga iz = −1.', 'Use y = 1, giving iz = −1.', String.raw`\sin i=\frac{e^{-1}-e}{2i}=i\frac{e-e^{-1}}2`),
        s('Baca nilai', 'Read the value', 'Hasil sinus murni imajiner; kosinus real dan lebih besar dari 1.', 'The sine is purely imaginary; the cosine is real and larger than 1.', String.raw`\sin i=i\sinh1,\quad \cos i=\cosh1>1`),
      ], b('Mengapa cos(i) bisa lebih dari 1?', 'Why can cos(i) exceed 1?'), b('Masukannya bukan real. Rumus eksponensial menghasilkan cosh(1), jadi batas kosinus real tidak berlaku.', 'The input is not real. The exponential formula gives cosh(1), so the real cosine bound does not apply.')),
    ],
    [
      l('integral', b('Mengapa integral lintasan memakai z′(t), dan dari mana batas ML berasal?', 'Why does a contour integral use z′(t), and where does the ML bound come from?'), [
        s('Pecah lintasan menjadi langkah kecil', 'Split the path into small steps', 'Lintasan z(t) memberi posisi. Perpindahan kecil sepanjang lintasan adalah dz = z′(t)dt; integral menjumlahkan f(z) dikali perpindahan itu.', 'The path z(t) gives position. Its small displacement is dz = z′(t)dt; the integral sums f(z) times those displacements.', String.raw`\int_\gamma f(z)\,dz=\int_a^b f(z(t))z'(t)\,dt`),
        s('Ambil besar setiap kontribusi', 'Bound each contribution', 'Ketaksamaan segitiga membatasi besar jumlah dengan jumlah besar. Jika |f| ≤ M sepanjang lintasan, ganti tiap |f| dengan M.', 'The triangle inequality bounds the size of a sum by the sum of sizes. If |f| ≤ M along the contour, replace each |f| by M.', String.raw`\left|\int_\gamma f\,dz\right|\le\int_a^b M|z'(t)|\,dt`),
        s('Kenali panjang lintasan', 'Recognize path length', 'Integral kecepatan |z′| adalah panjang L. Jadi besar integral paling banyak M kali panjang lintasan.', 'The integral of speed |z′| is path length L. Thus the integral’s magnitude is at most M times L.', String.raw`L=\int_a^b|z'(t)|dt,\quad \left|\int_\gamma f\,dz\right|\le ML`),
      ], [b('Gunakan lintasan mulus sepotong-sepotong dan f kontinu di lintasan. M adalah batas modulus di lintasan itu.', 'Use a piecewise smooth contour with f continuous on it. M bounds the modulus on that contour.')], b('ML adalah batas atas, bukan rumus nilai tepat. Kontribusi dengan arah berbeda dapat saling menghapus.', 'ML is an upper bound, not an exact evaluation. Contributions in different directions may cancel.'), [
        s('Parameterkan lingkaran', 'Parameterize the circle', 'Untuk z = eⁱᵗ, turunan z′ = ieⁱᵗ. Pada 1/z, kedua eksponensial saling menghapus.', 'For z = eⁱᵗ, z′ = ieⁱᵗ. With 1/z, the two exponentials cancel.', String.raw`\frac1{z(t)}z'(t)=e^{-it}ie^{it}=i`),
        s('Integralkan konstanta', 'Integrate the constant', 'Satu putaran berlawanan jarum jam memakai t dari 0 sampai 2π.', 'One counterclockwise turn uses t from 0 to 2π.', String.raw`\oint_{|z|=1}\frac{dz}{z}=\int_0^{2\pi}i\,dt=2\pi i`),
      ], b('Jika orientasi lingkaran dibalik, apa yang berubah?', 'What changes if the circle’s orientation is reversed?'), b('dz berubah arah, sehingga integral berubah tanda menjadi −2πi; panjang L tetap sama.', 'dz reverses direction, so the integral becomes −2πi; the length L stays the same.')),
      l('primitive', b('Mengapa beberapa integral hanya bergantung pada titik awal dan akhir?', 'Why do some integrals depend only on their endpoints?'), [
        s('Cari fungsi yang turunannya f', 'Find a function whose derivative is f', 'Antiturunan F memenuhi F′ = f. Sepanjang lintasan, aturan rantai memberi turunan F(z(t)) sama dengan integran.', 'An antiderivative F satisfies F′ = f. Along a path, the chain rule makes the derivative of F(z(t)) equal to the integrand.', String.raw`\frac{d}{dt}F(z(t))=f(z(t))z'(t)`),
        s('Jumlahkan perubahan', 'Add the changes', 'Integrasi turunan menambahkan semua perubahan kecil F. Perubahan tengah saling menghapus, menyisakan nilai akhir dikurangi awal.', 'Integrating the derivative adds all small changes in F. Intermediate changes cancel, leaving the endpoint difference.', String.raw`\int_\gamma f(z)dz=F(z_b)-F(z_a)`),
        s('Tutup lintasan', 'Close the path', 'Jika titik akhir sama dengan titik awal, selisihnya nol. Cauchy–Goursat memperluas kesimpulan nol ke kontur sederhana yang fungsi analitik di dalam dan di sekitarnya.', 'If the endpoints coincide, the difference is zero. Cauchy–Goursat extends this zero conclusion to a simple contour with the function analytic inside and near the contour.', String.raw`z_b=z_a\implies\oint_\gamma F'(z)dz=0`),
      ], [b('F harus menjadi satu antiturunan pada daerah yang memuat seluruh lintasan.', 'F must be one antiderivative on a domain containing the whole path.'), b('Analitik pada daerah terhubung sederhana menjamin antiturunan. Lubang atau singularitas di dalam kontur harus diperiksa.', 'Analyticity on a simply connected domain guarantees an antiderivative. Check holes or singularities inside the contour.')], b('1/z analitik di luar nol, tetapi mengelilingi nol memberi 2πi. Daerah berlubang itu tidak punya antiturunan global untuk 1/z.', '1/z is analytic away from zero, but circling zero gives 2πi. That punctured domain has no global antiderivative for 1/z.'), [
        s('Cari antiturunan', 'Find an antiderivative', 'z³/3 memiliki turunan z² pada seluruh C.', 'z³/3 differentiates to z² throughout C.', String.raw`F(z)=z^3/3,\quad F'(z)=z^2`),
        s('Gunakan ujung lintasan', 'Use the endpoints', 'Pada lintasan tertutup, nilai F di ujung sama dengan di awal.', 'On a closed contour, F has the same value at the end and beginning.', String.raw`\oint_\gamma z^2dz=F(z_a)-F(z_a)=0`),
      ], b('Apakah f analitik di kontur saja cukup untuk menyimpulkan integral nol?', 'Is analyticity on the contour alone enough to conclude zero?'), b('Tidak. 1/z pada lingkaran satuan adalah contoh gagal: ada singularitas di bagian dalam.', 'No. 1/z on the unit circle is a counterexample: there is a singularity inside.')),
      l('cauchy', b('Bagaimana integral di lingkaran dapat menentukan nilai fungsi di dalamnya?', 'How can an integral around a circle determine a function’s value inside?'), [
        s('Pisahkan nilai yang dicari', 'Separate the value you want', 'Tulis f(z) sebagai f(a) + [f(z)−f(a)]. Pembagian selisih dengan z−a punya singularitas yang dapat dihapus di a.', 'Write f(z) as f(a)+[f(z)−f(a)]. The difference divided by z−a has a removable singularity at a.', String.raw`\frac{f(z)}{z-a}=\frac{f(a)}{z-a}+\frac{f(z)-f(a)}{z-a}`),
        s('Hapus kontribusi analitik', 'Remove the analytic contribution', 'Suku selisih analitik setelah titik a diisi dengan f′(a), sehingga integral tertutupnya nol. Yang tersisa hanya f(a)/(z−a).', 'After defining its value at a as f′(a), the difference term is analytic and has zero closed integral. Only f(a)/(z−a) remains.', String.raw`\oint_\gamma\frac{f(z)-f(a)}{z-a}\,dz=0`),
        s('Hitung satu putaran', 'Count one turn', 'Integral 1/(z−a) pada satu putaran positif adalah 2πi. Karena f(a) konstan, hasilnya 2πi f(a).', 'The integral of 1/(z−a) over one positive turn is 2πi. Since f(a) is constant, the result is 2πi f(a).', String.raw`f(a)=\frac1{2\pi i}\oint_\gamma\frac{f(z)}{z-a}\,dz`),
      ], [b('f analitik pada lingkungan kontur sederhana tertutup dan seluruh bagian dalamnya; a berada di dalam, bukan di kontur.', 'f is analytic on a neighborhood of the simple closed contour and its entire interior; a is inside, not on the contour.'), b('Rumus ini memakai orientasi positif, yaitu berlawanan jarum jam.', 'This formula uses positive, counterclockwise orientation.')], b('Jika a di kontur, integran punya singularitas di lintasan. Rumus biasa tidak berlaku.', 'If a lies on the contour, the integrand is singular on the path. The ordinary formula does not apply.'), [
        s('Cocokkan bentuk', 'Match the form', 'Pembilang adalah f(z) = 1, titik a = 1, dan lingkaran radius 2 memuatnya.', 'The numerator is f(z) = 1, a = 1, and the circle of radius 2 encloses it.', String.raw`|1|<2,\qquad f(1)=1`),
        s('Ambil nilai di a', 'Sample at a', 'Tidak perlu menghitung seluruh parametrisasinya: rumus mengambil f(1).', 'No full parameterization is needed: the formula samples f(1).', String.raw`\oint_{|z|=2}\frac{dz}{z-1}=2\pi i\,f(1)=2\pi i`),
      ], b('Jika a = 3 dan kontur |z| = 2, apakah hasilnya masih 2πi?', 'If a = 3 and the contour is |z| = 2, is the result still 2πi?'), b('Tidak. 1/(z−3) analitik di dalam dan sekitar lingkaran itu, sehingga integralnya nol.', 'No. 1/(z−3) is analytic inside and near that circle, so the integral is zero.')),
    ],
    [
      l('series', b('Mengapa deret Laurent memakai pangkat negatif dan bergantung pada anulus?', 'Why does a Laurent series use negative powers and depend on an annulus?'), [
        s('Mulai dari deret geometri', 'Start with a geometric series', 'Identitas 1/(1−z) = 1+z+z²+… berasal dari jumlah geometri; sisanya zⁿ menuju nol hanya saat |z| < 1.', 'The identity 1/(1−z) = 1+z+z²+… comes from the geometric sum; the remainder zⁿ tends to zero only when |z| < 1.', String.raw`\frac1{1-z}=\sum_{n=0}^\infty z^n,\quad |z|<1`),
        s('Izinkan lubang di pusat', 'Allow a hole at the center', 'Mengalikan dengan 1/z menambah satu pangkat negatif. Taylor cocok untuk fungsi analitik sampai pusat; Laurent juga dapat menggambarkan fungsi pada cincin yang mengecualikan pusat.', 'Multiplication by 1/z adds a negative power. Taylor describes a function analytic at the center; Laurent can also describe it on a ring excluding the center.', String.raw`\frac1{z(1-z)}=z^{-1}+1+z+z^2+\cdots`),
        s('Tetapkan daerah konvergensi', 'Specify convergence', 'Nol harus dikecualikan karena faktor 1/z; singularitas di 1 membatasi radius luar. Pada daerah lain, fungsi sama dapat memiliki deret lain.', 'Zero is excluded because of 1/z; the singularity at 1 limits the outer radius. In another region, the same function may have another series.', String.raw`0<|z|<1`),
      ], [b('Nyatakan pusat dan daerah konvergensi. Deret Taylor berlaku dalam cakram; deret Laurent dalam anulus.', 'State the center and convergence region. Taylor series apply on discs; Laurent series on annuli.')], b('Deret yang benar pada 0 < |z| < 1 tidak boleh langsung digunakan di |z| > 1 atau di batas |z| = 1.', 'A series valid on 0 < |z| < 1 cannot be used directly for |z| > 1 or on |z| = 1.'), [
        s('Uraikan faktor', 'Expand the factor', 'Pada |z| < 1, faktor 1/(1−z) punya deret geometri.', 'For |z| < 1, 1/(1−z) has a geometric expansion.', String.raw`\frac1{z(1-z)}=\frac1z(1+z+z^2+\cdots)`),
        s('Geser pangkat', 'Shift the powers', 'Pembagian oleh z menurunkan semua pangkat satu tingkat. Koefisien z⁻¹ adalah 1.', 'Division by z lowers every power by one. The coefficient of z⁻¹ is 1.', String.raw`\operatorname{Res}(f,0)=c_{-1}=1`),
      ], b('Apakah nilai z = 0.5 boleh dimasukkan? Bagaimana z = 2?', 'May you substitute z = 0.5? What about z = 2?'), b('0.5 berada di anulus dan boleh. 2 berada di luar radius konvergensi; perlu ekspansi lain.', '0.5 lies in the annulus and is allowed. 2 lies outside the convergence radius and needs another expansion.')),
      l('singularities', b('Bagaimana pangkat negatif membedakan tiga jenis singularitas?', 'How do negative powers distinguish three kinds of singularity?'), [
        s('Lihat dekat titik yang hilang', 'Look near the missing point', 'Singularitas terisolasi berarti fungsi analitik pada cakram kecil yang pusatnya dikeluarkan. Laurent membaca perilakunya di cakram berlubang itu.', 'An isolated singularity means the function is analytic on a small punctured disc. Laurent describes its behavior on that punctured disc.', String.raw`0<|z-a|<R`),
        s('Hitung pangkat negatif', 'Count negative powers', 'Tidak ada pangkat negatif berarti nilai pusat dapat diisi. Jumlah hingga pangkat negatif berarti kutub; pangkat paling negatif menentukan orde kutub.', 'No negative powers means the center can be filled in. Finitely many negative powers mean a pole; the most negative power gives its order.', String.raw`\frac{c_{-m}}{(z-a)^m}+\cdots+\frac{c_{-1}}{z-a},\quad c_{-m}\ne0`),
        s('Kenali bagian utama tak hingga', 'Recognize an infinite principal part', 'Jika tak terhingga banyak koefisien pangkat negatif tidak nol, tidak ada perkalian dengan satu pangkat hingga yang menghilangkan singularitas: jenisnya esensial.', 'If infinitely many negative-power coefficients are nonzero, no single finite power removes the singularity: it is essential.', String.raw`e^{1/z}=1+z^{-1}+\frac{z^{-2}}{2!}+\cdots`),
      ], [b('Klasifikasi ini khusus singularitas terisolasi, bukan titik cabang atau titik akumulasi singularitas.', 'This classification applies to isolated singularities, not branch points or accumulation points of singularities.')], b('Log z di nol memiliki masalah cabang; jangan mengklasifikasikannya seperti kutub terisolasi biasa.', 'Log z at zero has a branch issue; do not classify it as an ordinary isolated pole.'), [
        s('Bandingkan dua bentuk', 'Compare two forms', 'sin z / z memiliki limit 1 sehingga pusat dapat diisi; 1/z memiliki satu pangkat negatif dan kutub orde 1.', 'sin z / z tends to 1, so the center can be filled; 1/z has one negative power and a pole of order 1.', String.raw`\frac{\sin z}{z}=1-\frac{z^2}{3!}+\cdots,\quad \frac1z=z^{-1}`),
        s('Bandingkan dengan esensial', 'Compare with essential', 'e^(1/z) mempunyai pangkat negatif tanpa akhir, jadi bukan kutub orde hingga.', 'e^(1/z) has endlessly many negative powers, so it is not a finite-order pole.', String.raw`c_{-n}=1/n!\ne0\quad(n\ge1)`),
      ], b('Jika bagian utama hanya 5/z³ + 2/z, berapa orde kutubnya?', 'If the principal part is 5/z³ + 2/z, what is the pole order?'), b('Orde 3, ditentukan oleh pangkat paling negatif; residunya tetap koefisien 1/z, yaitu 2.', 'Order 3, set by the most negative power; the residue is still the coefficient of 1/z, namely 2.')),
      l('residue', b('Mengapa hanya koefisien 1/(z−a) yang menentukan integral?', 'Why does only the 1/(z−a) coefficient determine the integral?'), [
        s('Integralkan setiap pangkat', 'Integrate each power', 'Pada lingkaran z−a = reⁱᵗ, dz = ireⁱᵗdt. Suku (z−a)ⁿ menghasilkan eksponensial dengan frekuensi n+1.', 'On a circle z−a = reⁱᵗ, dz = ireⁱᵗdt. The term (z−a)ⁿ produces an exponential with frequency n+1.', String.raw`\oint(z-a)^n dz=ir^{n+1}\int_0^{2\pi}e^{i(n+1)t}dt`),
        s('Satu frekuensi tidak menghapus', 'One frequency does not cancel', 'Jika n ≠ −1, satu putaran menghapus kontribusi eksponensial. Jika n = −1, eksponensialnya 1 dan tersisa 2πi.', 'If n ≠ −1, one full turn cancels the exponential contribution. At n = −1, the exponential is 1, leaving 2πi.', String.raw`\oint(z-a)^n dz=\begin{cases}2\pi i&n=-1\\0&n\ne-1\end{cases}`),
        s('Jumlahkan titik di dalam', 'Add the enclosed points', 'Kontur dapat dideformasi menjadi lingkaran kecil di sekitar singularitas tanpa menyeberanginya. Setiap lingkaran menyumbang 2πi kali residunya.', 'The contour can be deformed into small circles around the singularities without crossing them. Each circle contributes 2πi times its residue.', String.raw`\oint_\gamma f(z)dz=2\pi i\sum_{a\text{ inside}}\operatorname{Res}(f,a)`),
      ], [b('Untuk bentuk sederhana ini: kontur sederhana berorientasi positif, f analitik di dalam dan sekitar kontur kecuali sejumlah hingga singularitas terisolasi di dalam.', 'For this simple form: a positively oriented simple contour, with f analytic inside and near it except at finitely many isolated interior singularities.'), b('Tidak boleh ada singularitas di lintasan. Kontur umum memakai bilangan lilit untuk setiap singularitas.', 'No singularity may lie on the contour. General contours use the winding number of each singularity.')], b('Residu bukan semua bagian utama dan bukan orde kutub. Hanya koefisien pangkat −1 yang dipakai.', 'The residue is neither the whole principal part nor the pole order. Only the coefficient of power −1 is used.'), [
        s('Cari residu dua kutub', 'Find both residues', 'Untuk 1/[z(z−1)], pecahan parsial memberi −1/z + 1/(z−1). Residunya −1 di 0 dan 1 di 1.', 'For 1/[z(z−1)], partial fractions give −1/z + 1/(z−1). The residues are −1 at 0 and 1 at 1.', String.raw`\frac1{z(z-1)}=-\frac1z+\frac1{z-1}`),
        s('Jumlahkan yang dilingkari', 'Sum the enclosed residues', 'Lingkaran |z| = 2 memuat kedua kutub; kontribusinya saling menghapus.', 'The circle |z| = 2 encloses both poles; their contributions cancel.', String.raw`\oint_{|z|=2}\frac{dz}{z(z-1)}=2\pi i(-1+1)=0`),
      ], b('Bagaimana jika kontur hanya mengelilingi nol?', 'What if the contour encloses only zero?'), b('Jumlah residunya hanya −1, sehingga integral satu putaran positif adalah −2πi.', 'The residue sum is just −1, so one positive turn gives −2πi.')),
    ],
  ],
  geometry: [
    [
      l('basis', b('Mengapa vektor perpindahan adalah Q−P, dan kapan koordinatnya unik?', 'Why is displacement Q−P, and when are its coordinates unique?'), [
        s('Pisahkan posisi dari perpindahan', 'Separate position from displacement', 'P dan Q adalah posisi relatif terhadap asal. Untuk berjalan dari P ke Q, kurangi bagian perjalanan yang sudah mencapai P.', 'P and Q are positions relative to an origin. To travel from P to Q, subtract the portion of the journey already reaching P.', String.raw`\overrightarrow{PQ}=\overrightarrow{OQ}-\overrightarrow{OP}=Q-P`),
        s('Susun dari arah dasar', 'Build from basic directions', 'Basis menyediakan arah yang bebas linear. Koefisien aᵢ mengatakan seberapa jauh bergerak pada setiap arah; gabungannya menghasilkan v.', 'A basis supplies linearly independent directions. Each coefficient aᵢ says how far to move in one direction; together they produce v.', String.raw`v=a_1e_1+\cdots+a_ne_n`),
        s('Periksa keunikan', 'Check uniqueness', 'Jika dua daftar koefisien memberi v sama, selisihnya memberi kombinasi basis bernilai nol. Kebebasan linear memaksa semua selisih koefisien nol.', 'If two coefficient lists give the same v, their difference gives a zero combination of basis vectors. Linear independence forces every coefficient difference to be zero.', String.raw`\sum_i(a_i-b_i)e_i=0\implies a_i=b_i`),
      ], [b('Untuk koordinat unik di ruang berdimensi n, gunakan n vektor bebas linear yang merentang seluruh ruang.', 'For unique coordinates in n dimensions, use n independent vectors spanning the entire space.'), b('Rumus panjang √(a₁²+…+aₙ²) memakai basis ortonormal; pada basis lain perlu matriks hasil kali skalar.', 'The length formula √(a₁²+…+aₙ²) assumes an orthonormal basis; another basis needs its inner-product matrix.')], b('Dua arah sejajar tidak membentuk basis bidang; banyak titik tidak dapat dicapai dan beberapa koordinat tidak unik.', 'Two parallel directions are not a basis of the plane; some points are unreachable and some coordinates are nonunique.'), [
        s('Kurangi posisi', 'Subtract positions', 'Dari P = (2,3) ke Q = (5,7), perubahan mendatar 3 dan perubahan tegak 4.', 'From P = (2,3) to Q = (5,7), the horizontal change is 3 and the vertical change is 4.', String.raw`Q-P=(5-2,7-3)=(3,4)`),
        s('Ukur perpindahan', 'Measure the displacement', 'Pada sumbu ortonormal, Pythagoras memberi jarak 5. Menggeser asal koordinat tidak mengubah selisih ini.', 'On orthonormal axes, Pythagoras gives distance 5. Moving the coordinate origin does not change this difference.', String.raw`|PQ|=\sqrt{3^2+4^2}=5`),
      ], b('Jika asal digeser oleh c, apa yang terjadi pada Q−P?', 'If the origin shifts by c, what happens to Q−P?'), b('Tidak berubah: (Q−c)−(P−c) = Q−P. Posisi berubah, perpindahan tetap.', 'It stays the same: (Q−c)−(P−c) = Q−P. Positions change; displacement does not.')),
      l('products', b('Mengapa dot product memberi sudut, cross product memberi luas, dan triple product memberi volume?', 'Why does the dot product give angle, the cross product area, and the triple product volume?'), [
        s('Bandingkan dua rumus panjang', 'Compare two length formulas', 'Kembangkan |a−b|² dengan koordinat, lalu bandingkan dengan hukum kosinus. Suku silang yang sama memberi a·b = |a||b| cos θ.', 'Expand |a−b|² in coordinates and compare with the cosine rule. Matching the cross term gives a·b = |a||b| cos θ.', String.raw`|a-b|^2=|a|^2+|b|^2-2a\cdot b`),
        s('Ambil luas dan arah tegak lurus', 'Take area and a perpendicular direction', 'Luas jajargenjang adalah alas |a| kali tinggi |b| sin θ. Cross product adalah vektor tegak lurus dengan panjang luas itu; arahnya mengikuti aturan tangan kanan.', 'A parallelogram’s area is base |a| times height |b| sin θ. The cross product is a perpendicular vector with that length, directed by the right-hand rule.', String.raw`|a\times b|=|a||b|\sin\theta`),
        s('Proyeksikan tinggi volume', 'Project the volume’s height', 'Dot product dari vektor luas a×b dengan c mengambil komponen c sepanjang normal. Hasilnya alas kali tinggi, dengan tanda orientasi.', 'Dotting the area vector a×b with c extracts c’s normal component. The result is base area times height, with an orientation sign.', String.raw`V_{\text{signed}}=(a\times b)\cdot c=\det(a,b,c)`),
      ], [b('Sudut memerlukan dua vektor tidak nol. Cross product bentuk ini memakai ruang Euclidean 3D berorientasi.', 'An angle requires two nonzero vectors. This cross product uses oriented Euclidean 3D space.'), b('Volume biasa adalah nilai mutlak triple product; nol berarti ketiga vektor sebidang.', 'Ordinary volume is the absolute triple product; zero means the three vectors are coplanar.')], b('Dot product bernilai nol juga jika salah satu vektor nol; jangan menyebut sudutnya 90° karena sudut vektor nol tidak terdefinisi.', 'The dot product is also zero if one vector is zero; do not call the angle 90°, because a zero vector has no defined angle.'), [
        s('Periksa sumbu tegak lurus', 'Check perpendicular axes', 'e₁ dan e₂ satuan dan saling tegak lurus; dot product nol dan luas persegi satu.', 'e₁ and e₂ are perpendicular unit vectors; their dot product is zero and their unit square has area one.', String.raw`e_1\cdot e_2=0,\quad e_1\times e_2=e_3`),
        s('Tambahkan tinggi', 'Add height', 'e₃ memiliki tinggi 1 pada arah normal. Volume kubus satuan adalah 1.', 'e₃ has height 1 in the normal direction. The unit cube’s volume is 1.', String.raw`(e_1\times e_2)\cdot e_3=1`),
      ], b('Apa yang berubah ketika a dan b ditukar?', 'What changes when a and b are swapped?'), b('Dot product tetap. Cross product dan triple product membalik tanda; luas dan volume tanpa tanda tetap.', 'The dot product stays the same. The cross and triple products reverse sign; unsigned area and volume stay the same.')),
    ],
    [
      l('plane', b('Mengapa garis memakai arah, tetapi bidang memakai normal?', 'Why does a line use a direction but a plane use a normal?'), [
        s('Gerakkan titik di satu arah', 'Move a point in one direction', 'Mulai dari p dan bergerak sejauh t kali arah d. Semua posisi yang diperoleh adalah garis; t dapat positif, negatif, atau nol.', 'Start at p and move t times the direction d. All resulting positions form a line; t may be positive, negative, or zero.', String.raw`r=p+td`),
        s('Batasi perpindahan dalam bidang', 'Restrict motion to the plane', 'Bidang melalui p memuat perpindahan yang tegak lurus normal n. Dot product nol menyatakan syarat itu tanpa memilih dua arah dalam bidang.', 'A plane through p contains displacements perpendicular to its normal n. A zero dot product expresses that condition without choosing two in-plane directions.', String.raw`n\cdot(r-p)=0\iff n\cdot r=n\cdot p`),
        s('Cari tempat keduanya bertemu', 'Find where they meet', 'Masukkan r = p+td ke persamaan bidang. Satu persamaan linear menentukan t jika arah garis punya komponen normal tidak nol.', 'Substitute r = p+td into the plane equation. One linear equation determines t if the line direction has a nonzero normal component.', String.raw`n\cdot p+t(n\cdot d)=c`),
      ], [b('Arah d ≠ 0 dan normal n ≠ 0. Parameter t bukan selalu jarak kecuali d vektor satuan.', 'Direction d ≠ 0 and normal n ≠ 0. Parameter t is not necessarily distance unless d is a unit vector.')], b('Jika n·d = 0, jangan membagi dengannya: garis sejajar bidang; garis seluruhnya di bidang jika n·p = c, atau tidak berpotongan jika berbeda.', 'If n·d = 0, do not divide by it: the line is parallel to the plane; it lies in the plane if n·p = c, and otherwise never meets it.'), [
        s('Substitusi garis', 'Substitute the line', 'Garis (t,t,t) punya arah (1,1,1), sama dengan normal bidang x+y+z = 3.', 'The line (t,t,t) has direction (1,1,1), matching the normal of x+y+z = 3.', String.raw`t+t+t=3`),
        s('Ambil posisi saat t = 1', 'Read the position at t = 1', 'Persamaan memberi t = 1. Masukkan ke ketiga koordinat untuk memperoleh satu titik potong.', 'The equation gives t = 1. Substitute into all three coordinates to obtain the intersection.', String.raw`t=1,\quad r(1)=(1,1,1)`),
      ], b('Mengapa n = (0,0,0) tidak mendefinisikan bidang?', 'Why does n = (0,0,0) fail to define a plane?'), b('Persamaannya menjadi 0 = c: semua ruang jika c = 0, atau himpunan kosong jika c ≠ 0.', 'The equation becomes 0 = c: all of space if c = 0, or the empty set if c ≠ 0.')),
      l('projection', b('Mengapa rumus jarak titik ke bidang dibagi panjang normal?', 'Why is point-to-plane distance divided by the normal’s length?'), [
        s('Pilih titik kaki', 'Choose a point on the plane', 'Ambil Q pada bidang dan titik P di luar. Vektor P−Q mencakup perpindahan mendatar dalam bidang dan tegak lurus bidang.', 'Take Q on the plane and a point P outside. P−Q contains both an in-plane displacement and one perpendicular to the plane.', String.raw`n\cdot Q=c`),
        s('Ambil komponen normal', 'Take the normal component', 'Jarak terpendek hanya bagian tegak lurus. Dot dengan normal satuan n/|n| mengambil panjang berarah pada arah itu.', 'The shortest distance is just the perpendicular part. Dotting with the unit normal n/|n| extracts the signed length in that direction.', String.raw`\text{signed distance}=\frac{n\cdot(P-Q)}{|n|}`),
        s('Hilangkan Q dan tanda', 'Remove Q and the sign', 'Karena n·Q = c, pembilang menjadi n·P−c. Nilai mutlak memastikan jarak tidak negatif.', 'Since n·Q = c, the numerator becomes n·P−c. The absolute value makes distance nonnegative.', String.raw`d=\frac{|n\cdot P-c|}{|n|}`),
      ], [b('n ≠ 0 dan koordinat Euclidean ortonormal. Sudut antara garis atau bidang dihitung melalui arah atau normal yang tidak nol.', 'n ≠ 0 and orthonormal Euclidean coordinates are required. Line or plane angles use nonzero direction or normal vectors.')], b('Mengalikan seluruh persamaan bidang dengan 10 tidak mengubah jarak: pembilang dan penyebut sama-sama dikalikan 10.', 'Multiplying the whole plane equation by 10 cannot change distance: both numerator and denominator scale by 10.'), [
        s('Temukan normal dan konstanta', 'Identify normal and constant', 'Bidang x+y+z = 3 memiliki n = (1,1,1). Untuk asal, n·P−c = −3.', 'The plane x+y+z = 3 has n = (1,1,1). At the origin, n·P−c = −3.', String.raw`|n|=\sqrt3,\quad |n\cdot P-c|=3`),
        s('Normalkan ukurannya', 'Normalize the measurement', 'Pembagian 3 dengan √3 memberi panjang sebenarnya, √3.', 'Dividing 3 by √3 gives the actual length, √3.', String.raw`d=3/\sqrt3=\sqrt3`),
      ], b('Apa arti pembilang bertanda nol?', 'What does a zero signed numerator mean?'), b('Titik memenuhi persamaan bidang, jadi terletak pada bidang dan jaraknya nol.', 'The point satisfies the plane equation, so it lies on the plane and has distance zero.')),
    ],
    [
      l('power', b('Dari mana kuasa titik dan persamaan polar lingkaran berasal?', 'Where do point power and the circle’s polar equation come from?'), [
        s('Mulai dari jarak ke pusat', 'Start with distance to the center', 'Lingkaran berpusat O berjari-jari R memenuhi |X−O|² = R². Selisih |P−O|²−R² mengukur apakah P di luar, di dalam, atau pada lingkaran.', 'A circle centered at O with radius R satisfies |X−O|² = R². The difference |P−O|²−R² determines whether P is outside, inside, or on it.', String.raw`\operatorname{Pow}(P)=|P-O|^2-R^2`),
        s('Gunakan segitiga garis singgung', 'Use a tangent right triangle', 'Di titik singgung T, radius OT tegak lurus PT. Pythagoras memberi |PT|² = |PO|²−R²; jadi kuasa adalah kuadrat panjang singgung untuk P di luar.', 'At a tangent point T, radius OT is perpendicular to PT. Pythagoras gives |PT|² = |PO|²−R²; thus power is squared tangent length for an exterior P.', String.raw`(P-T)\cdot(T-O)=0`),
        s('Hubungkan titik-titik singgung', 'Join the tangent points', 'Gunakan |T−O|² = R² dalam syarat tegak lurus. Hasilnya (P−O)·(T−O) = R². Mengganti T dengan X memberi garis polar.', 'Use |T−O|² = R² in the perpendicularity condition. This gives (P−O)·(T−O) = R². Replacing T by X defines the polar line.', String.raw`(P-O)\cdot(X-O)=R^2`),
      ], [b('R > 0. Panjang singgung real hanya ada untuk titik di luar atau pada lingkaran.', 'R > 0. Real tangent lengths exist only for exterior points or points on the circle.'), b('Polar biasa memerlukan P ≠ O; untuk titik pada lingkaran, polar menjadi garis singgung.', 'An ordinary polar line requires P ≠ O; for a point on the circle, it is the tangent.')], b('Kuasa negatif bukan kuadrat panjang singgung real. Artinya titik berada di dalam lingkaran.', 'Negative power is not a real squared tangent length. It means the point is inside the circle.'), [
        s('Hitung kuasa', 'Compute the power', 'Untuk lingkaran radius 2 dan P = (3,0), jarak pusat 3 lebih besar dari radius.', 'For a radius-2 circle and P = (3,0), the center distance 3 exceeds the radius.', String.raw`\operatorname{Pow}(P)=3^2-2^2=5`),
        s('Bentuk polar', 'Form the polar', 'Masukkan P ke dot product: 3x+0y = 4. Garis polar adalah x = 4/3.', 'Insert P into the dot product: 3x+0y = 4. The polar line is x = 4/3.', String.raw`3x=4\implies x=4/3`),
      ], b('Jika P berada tepat pada lingkaran, berapa kuasanya?', 'If P is on the circle, what is its power?'), b('Nol, karena jarak ke pusat sama dengan radius. Polarnya adalah garis singgung di P.', 'Zero, since its center distance equals the radius. Its polar is the tangent at P.')),
      l('radical', b('Mengapa mengurangkan dua persamaan lingkaran menghasilkan garis?', 'Why does subtracting two circle equations produce a line?'), [
        s('Bandingkan kuasa pada titik sama', 'Compare power at the same point', 'Kuasa terhadap lingkaran i adalah x²+y²−2aᵢx−2bᵢy+aᵢ²+bᵢ²−Rᵢ². Dua kuasa memakai bagian kuadrat yang sama.', 'Power relative to circle i is x²+y²−2aᵢx−2bᵢy+aᵢ²+bᵢ²−Rᵢ². Both powers share the same quadratic part.', String.raw`\operatorname{Pow}_{C_1}(P)=\operatorname{Pow}_{C_2}(P)`),
        s('Hapus bagian kuadrat', 'Cancel the quadratic part', 'Saat persamaan dikurangkan, x² dan y² hilang. Yang tersisa hanya suku linear dan konstanta: sumbu radikal.', 'Subtracting cancels x² and y². Only linear terms and a constant remain: the radical axis.', String.raw`2(O_2-O_1)\cdot P=|O_2|^2-|O_1|^2+R_1^2-R_2^2`),
        s('Baca arah dan perluas ke sphere', 'Read direction and extend to spheres', 'Normal garisnya searah garis penghubung pusat, sehingga sumbu radikal tegak lurus garis pusat. Pada bola 3D, pengurangan yang sama menghasilkan bidang radikal.', 'Its normal runs along the line joining the centers, so the radical axis is perpendicular to that line. For 3D spheres, the same subtraction yields a radical plane.', String.raw`C_\lambda:\quad C_1+\lambda C_2=0`),
      ], [b('Pusat berbeda memberi satu sumbu radikal. Anggota pencil C₁+λC₂ perlu diperiksa: untuk λ = −1 bagian kuadrat hilang.', 'Distinct centers give one radical axis. Check members of the pencil C₁+λC₂: at λ = −1 the quadratic part disappears.')], b('Lingkaran konsentris dengan radius berbeda tidak punya titik berkuasa sama; lingkaran identik punya kuasa sama di semua titik.', 'Concentric circles with different radii have no equal-power points; identical circles have equal power everywhere.'), [
        s('Samakan kuasa', 'Set powers equal', 'Pusat (−1,0) dan (1,0) mempunyai radius sama, jadi suku radius saling menghapus.', 'Centers (−1,0) and (1,0) have equal radii, so the radius terms cancel.', String.raw`(x+1)^2+y^2=(x-1)^2+y^2`),
        s('Kembangkan dan kurangkan', 'Expand and subtract', 'Selisihnya 4x = 0; semua titik pada sumbu y punya kuasa sama.', 'The difference is 4x = 0; every point on the y-axis has equal power.', String.raw`4x=0\implies x=0`),
      ], b('Apakah sumbu radikal tetap ada jika lingkaran tidak berpotongan?', 'Does the radical axis exist when the circles do not intersect?'), b('Ya, jika pusat berbeda. Syaratnya kuasa sama, bukan keharusan terletak di kedua lingkaran.', 'Yes, for distinct centers. Its condition is equal power, not lying on both circles.')),
    ],
    [
      l('conic', b('Dari mana persamaan kanonik elips, hiperbola, dan parabola berasal?', 'Where do canonical ellipse, hyperbola, and parabola equations come from?'), [
        s('Tetapkan aturan jarak', 'Specify a distance rule', 'Elips mempunyai jumlah jarak ke dua fokus konstan 2a. Hiperbola mempunyai selisih mutlak 2a. Parabola mempunyai jarak ke fokus sama dengan jarak ke direktriks.', 'An ellipse has constant summed focal distances 2a. A hyperbola has constant absolute difference 2a. A parabola has equal distances to a focus and directrix.', String.raw`\text{ellipse}:\quad |PF_+|+|PF_-|=2a`),
        s('Pilih sumbu sepanjang fokus', 'Align the axis with the foci', 'Letakkan fokus elips pada (±c,0). Jarak memakai akar kuadrat. Pindahkan satu akar, kuadratkan, lalu ulangi untuk menghilangkan akar.', 'Place the ellipse’s foci at (±c,0). Distances contain square roots. Isolate one radical, square, then repeat to eliminate the radicals.', String.raw`\sqrt{(x-c)^2+y^2}+\sqrt{(x+c)^2+y^2}=2a`),
        s('Baca hubungan parameter', 'Read parameter relations', 'Penyederhanaan memberi b² = a²−c². Pada hiperbola tandanya berubah, c² = a²+b². Untuk fokus (p,0) dan direktriks x = −p, parabola memberi y² = 4px.', 'Simplification gives b² = a²−c². For a hyperbola the sign changes: c² = a²+b². A focus (p,0) and directrix x = −p give y² = 4px.', String.raw`\frac{x^2}{a^2}+\frac{y^2}{a^2-c^2}=1`),
      ], [b('Elips nondegenerat: a > c ≥ 0 dan b > 0. Hiperbola: a,b > 0. Parabola: p ≠ 0 pada konvensi y² = 4px.', 'Nondegenerate ellipse: a > c ≥ 0 and b > 0. Hyperbola: a,b > 0. Parabola: p ≠ 0 in the y² = 4px convention.')], b('Mengkuadratkan bisa menambah solusi palsu. Periksa kembali aturan jarak asal dan batas parameternya.', 'Squaring can introduce extraneous solutions. Check the original distance rule and parameter restrictions.'), [
        s('Baca sumbu', 'Read the axes', 'x²/9+y²/4 = 1 memberi a = 3 dan b = 2; sumbu panjangnya mendatar.', 'x²/9+y²/4 = 1 gives a = 3 and b = 2; its major axis is horizontal.', String.raw`a^2=9,\quad b^2=4`),
        s('Cari fokus', 'Locate the foci', 'Gunakan c² = a²−b² = 5. Fokus berjarak √5 dari pusat pada sumbu x.', 'Use c² = a²−b² = 5. The foci are √5 from the center along the x-axis.', String.raw`F_\pm=(\pm\sqrt5,0)`),
      ], b('Mengapa elips memakai c² = a²−b², bukan jumlahnya?', 'Why does an ellipse use c² = a²−b² rather than a sum?'), b('Pada ujung sumbu pendek (0,b), kedua jarak fokus sama dengan a. Pythagoras memberi a² = b²+c².', 'At the minor-axis endpoint (0,b), both focal distances equal a. Pythagoras gives a² = b²+c².')),
      l('quadric', b('Bagaimana irisan membantu membaca permukaan 3D, dan mengapa pelana punya garis lurus?', 'How do slices explain 3D surfaces, and why does a saddle contain straight lines?'), [
        s('Bekukan satu koordinat', 'Freeze one coordinate', 'Persamaan kuadrik memiliki derajat dua. Menetapkan z = k menghasilkan kurva 2D; perubahan k menunjukkan bagaimana irisan tersusun menjadi permukaan.', 'A quadric equation has degree two. Setting z = k produces a 2D curve; changing k shows how the slices assemble into a surface.', String.raw`z=x^2-y^2\implies x^2-y^2=k`),
        s('Faktorkan selisih kuadrat', 'Factor the difference of squares', 'Pada pelana, x²−y² = (x+y)(x−y). Koordinat baru s = x+y dan t = x−y memberi z = st.', 'On the saddle, x²−y² = (x+y)(x−y). New coordinates s = x+y and t = x−y give z = st.', String.raw`s=x+y,\quad t=x-y,\quad z=st`),
        s('Tahan satu faktor', 'Hold one factor fixed', 'Dengan s = c, x = (c+t)/2, y = (c−t)/2, z = ct. Ketiganya linear terhadap t, jadi membentuk garis lurus. Menahan t memberi keluarga kedua.', 'With s = c, x = (c+t)/2, y = (c−t)/2, z = ct. All three are linear in t, hence a straight line. Holding t fixed gives a second family.', String.raw`r(t)=\left(\frac{c+t}2,\frac{c-t}2,ct\right)`),
      ], [b('Garis pembangun ini khusus kuadrik tertentu, seperti paraboloid hiperbolik dan hiperboloid satu lembar; ellipsoid tidak mempunyai garis lurus pada permukaannya.', 'These rulings occur on particular quadrics, such as the hyperbolic paraboloid and one-sheet hyperboloid; an ellipsoid contains no straight surface lines.')], b('Gambar perspektif saja dapat menipu. Gunakan beberapa irisan dan tanda koefisien, bukan siluet saja.', 'Perspective alone can mislead. Use several slices and coefficient signs, not just the silhouette.'), [
        s('Tetapkan s = 2', 'Set s = 2', 'Jika x+y = 2, biarkan t = x−y bergerak.', 'With x+y = 2, let t = x−y vary.', String.raw`x=1+t/2,\quad y=1-t/2`),
        s('Periksa garisnya', 'Verify the line', 'Selisih kuadratnya menjadi 2t, sama dengan z. Setiap titik garis ini berada pada pelana.', 'The difference of squares becomes 2t, equal to z. Every point on this line lies on the saddle.', String.raw`x^2-y^2=2t=z`),
      ], b('Apa bentuk irisan z = 0 pada pelana ini?', 'What is the slice z = 0 on this saddle?'), b('x²−y² = 0 memberi dua garis x = y dan x = −y, bukan lingkaran.', 'x²−y² = 0 gives two lines x = y and x = −y, not a circle.')),
      l('eigen', b('Mengapa eigenvector menghilangkan suku xy?', 'Why do eigenvectors remove the xy term?'), [
        s('Simpan koefisien dalam matriks', 'Store coefficients in a matrix', 'xᵀAx memberi Ax² + 2Bxy + Cy² bila matriks simetrisnya [[A,B],[B,C]]. Koefisien xy terbagi ke dua entri yang simetris.', 'xᵀAx gives Ax²+2Bxy+Cy² for the symmetric matrix [[A,B],[B,C]]. The xy coefficient is split across two symmetric entries.', String.raw`q(x)=x^TAx`),
        s('Pilih arah yang tidak saling bercampur', 'Choose directions that do not mix', 'Matriks real simetris punya basis eigen ortonormal. Letakkan eigenvector sebagai kolom Q; setiap arah hanya diskalakan oleh eigenvalue-nya.', 'A real symmetric matrix has an orthonormal eigenbasis. Place its eigenvectors in the columns of Q; each direction is scaled only by its eigenvalue.', String.raw`Q^TAQ=\operatorname{diag}(\lambda_1,\lambda_2)`),
        s('Ganti koordinat', 'Change coordinates', 'Tulis x = Qy. Bentuk kuadrat menjadi λ₁y₁²+λ₂y₂², tanpa suku silang. Untuk mencari pusat pada bentuk lengkap, hilangkan gradien: 2Ah+b = 0.', 'Write x = Qy. The quadratic form becomes λ₁y₁²+λ₂y₂² with no mixed term. To find a center of the full equation, set its gradient to zero: 2Ah+b = 0.', String.raw`x^TAx=y^T(Q^TAQ)y=\lambda_1y_1^2+\lambda_2y_2^2`),
      ], [b('A harus real simetris; gunakan eigenvector yang dinormalisasi. Pusat unik jika A invertibel.', 'A must be real symmetric; normalize its eigenvectors. The center is unique if A is invertible.')], b('Jika A singular, 2Ah+b = 0 dapat mempunyai banyak solusi atau tidak ada; rumus h = −½A⁻¹b tidak boleh dipakai.', 'If A is singular, 2Ah+b = 0 may have many solutions or none; h = −½A⁻¹b cannot be used.'), [
        s('Cari dua arah', 'Find two directions', 'Untuk A = [[1,1],[1,1]], arah (1,1) mempunyai eigenvalue 2; arah (1,−1) mempunyai eigenvalue 0.', 'For A = [[1,1],[1,1]], direction (1,1) has eigenvalue 2; direction (1,−1) has eigenvalue 0.', String.raw`q_1=(1,1)/\sqrt2,\quad q_2=(1,-1)/\sqrt2`),
        s('Putar ke koordinat utama', 'Rotate to principal coordinates', 'x+y = √2y₁, sehingga (x+y)² = 2y₁². Tidak ada kelengkungan pada arah y₂.', 'x+y = √2y₁, so (x+y)² = 2y₁². There is no curvature along y₂.', String.raw`x^2+2xy+y^2=2y_1^2+0y_2^2`),
      ], b('Mengapa koefisien xy = 2 memberi entri luar diagonal 1?', 'Why does an xy coefficient of 2 give off-diagonal entries 1?'), b('Dalam xᵀAx, entri (1,2) dan (2,1) masing-masing menyumbang xy; jumlahnya 2xy.', 'In xᵀAx, entries (1,2) and (2,1) each contribute xy; together they give 2xy.')),
      l('reduce', b('Bagaimana melengkapkan kuadrat mengungkap pusat dan jenis kurva?', 'How does completing squares reveal a curve’s center and type?'), [
        s('Buat kuadrat sempurna', 'Create a perfect square', 'x²+bx = (x+b/2)²−b²/4. Tambahkan dan kurangkan konstanta yang sama agar persamaan tidak berubah.', 'x²+bx = (x+b/2)²−b²/4. Add and subtract the same constant so the equation remains unchanged.', String.raw`x^2+bx=(x+b/2)^2-b^2/4`),
        s('Pindahkan asal koordinat', 'Move the coordinate origin', 'Setelah suku linear hilang, variabel baru mengukur posisi relatif terhadap pusat. Jika ada xy, diagonaliskan bagian kuadrat terlebih dahulu atau gunakan translasi matriks.', 'After the linear terms vanish, new variables measure position relative to the center. If xy is present, diagonalize the quadratic part or use matrix translation.', String.raw`X=x-h,\quad Y=y-k`),
        s('Periksa tanda dan konstanta', 'Check signs and the constant', 'Dua kuadrat dengan tanda sama dan ruas kanan positif memberi elips. Tanda berbeda memberi hiperbola. Nilai nol atau negatif dapat memberi bentuk degenerat atau himpunan kosong.', 'Two squares of the same sign with positive right side give an ellipse. Opposite signs give a hyperbola. A zero or negative constant can give a degenerate set or no real points.', String.raw`X^2+Y^2=R^2`),
      ], [b('Klasifikasi harus mempertimbangkan rank, tanda eigenvalue, suku linear pada arah nol, dan konstanta hasil reduksi.', 'Classification must consider rank, eigenvalue signs, linear terms in null directions, and the reduced constant.')], b('Dua eigenvalue positif tidak selalu berarti elips nyata: X²+Y² = −1 tidak mempunyai titik real.', 'Two positive eigenvalues do not always give a real ellipse: X²+Y² = −1 has no real points.'), [
        s('Tambahkan konstanta yang diperlukan', 'Add the needed constants', 'x²+4x membutuhkan +4; y²−2y membutuhkan +1. Tambahkan 5 pada kedua sisi.', 'x²+4x needs +4; y²−2y needs +1. Add 5 to both sides.', String.raw`x^2+4x+4+y^2-2y+1=5`),
        s('Baca hasil geometri', 'Read the geometry', 'Kuadratnya mengukur jarak dari (−2,1). Jumlah kuadrat jarak adalah 5, jadi radius √5.', 'The squares measure displacement from (−2,1). Their squared distance sums to 5, so the radius is √5.', String.raw`(x+2)^2+(y-1)^2=5`),
      ], b('Mengapa pusat x adalah −2, bukan 2?', 'Why is the center’s x-coordinate −2 rather than 2?'), b('Jarak mendatar dari pusat adalah x−h. Karena x+2 = x−(−2), maka h = −2.', 'Horizontal displacement from the center is x−h. Since x+2 = x−(−2), h = −2.')),
    ],
    [
      l('affine', b('Mengapa transformasi afin menjaga garis dan kesejajaran?', 'Why does an affine transformation preserve lines and parallelism?'), [
        s('Pisahkan matriks dan perpindahan', 'Separate matrix and translation', 'A mengubah vektor melalui kombinasi linear; b menggeser semua titik dengan perpindahan yang sama.', 'A changes vectors by a linear combination; b shifts every point by the same displacement.', String.raw`T(x)=Ax+b`),
        s('Transformasikan garis', 'Transform a line', 'Masukkan x = p+td. Linearitas A memberi satu titik awal baru dan satu arah baru Ad.', 'Substitute x = p+td. Linearity gives one new starting point and one new direction Ad.', String.raw`T(p+td)=Ap+b+tAd`),
        s('Bandingkan dua garis', 'Compare two lines', 'Garis sejajar memiliki arah sama atau proporsional. Matriks mempertahankan hubungan proporsional itu. Translasi b tidak muncul dalam selisih dua titik.', 'Parallel lines have equal or proportional directions. The matrix preserves proportionality. Translation b disappears when subtracting two points.', String.raw`T(q)-T(p)=A(q-p)`),
      ], [b('Transformasi afin invertibel memerlukan det A ≠ 0 dan menjaga garis berbeda tetap berbeda. Peta afin singular dapat meruntuhkan garis menjadi titik.', 'An invertible affine transformation requires det A ≠ 0 and keeps distinct lines distinct. A singular affine map can collapse a line to a point.')], b('Peta afin umum tidak menjaga panjang atau sudut. Kesejajaran tidak berarti bentuk dan ukuran tetap.', 'A general affine map does not preserve lengths or angles. Preserved parallelism does not imply preserved shape or size.'), [
        s('Terapkan bagian linear', 'Apply the linear part', 'A = diag(2,1) membawa (1,2) ke (2,2). Hanya komponen x yang diperbesar.', 'A = diag(2,1) takes (1,2) to (2,2). Only the x-component is stretched.', String.raw`A(1,2)=(2,2)`),
        s('Tambahkan translasi', 'Add the translation', 'b = (1,−1) membawa titik itu ke (3,1).', 'b = (1,−1) moves that point to (3,1).', String.raw`T(1,2)=(2,2)+(1,-1)=(3,1)`),
      ], b('Apakah b mengubah jarak antara dua titik?', 'Does b change the distance between two points?'), b('Tidak. b saling menghapus dalam T(q)−T(p). Perubahan jarak datang dari A.', 'No. b cancels in T(q)−T(p). A is responsible for any distance change.')),
      l('isometry', b('Mengapa AᵀA = I berarti panjang dan sudut terjaga?', 'Why does AᵀA = I preserve lengths and angles?'), [
        s('Ukur panjang setelah transformasi', 'Measure length after transformation', 'Kuadrat panjang v adalah vᵀv. Untuk Av, transpose perkalian memberi vᵀAᵀAv.', 'The squared length of v is vᵀv. For Av, transposing the product gives vᵀAᵀAv.', String.raw`|Av|^2=(Av)^TAv=v^TA^TAv`),
        s('Minta ukuran yang sama', 'Require the same measurement', 'Jika AᵀA = I, panjang kembali menjadi vᵀv untuk semua v. Dot product juga tetap, sehingga sudut antara vektor tidak nol tetap.', 'If AᵀA = I, length returns to vᵀv for every v. Dot products also remain unchanged, so angles between nonzero vectors are preserved.', String.raw`(Au)\cdot(Av)=u^TA^TAv=u\cdot v`),
        s('Bedakan rotasi, refleksi, dan similaritas', 'Distinguish rotation, reflection, and similarity', 'Matriks ortogonal memiliki det ±1: +1 menjaga orientasi, −1 membalikkannya. Mengalikan matriks ortogonal Q dengan skala s memperbesar semua jarak sebesar |s|.', 'Orthogonal matrices have det ±1: +1 preserves orientation, −1 reverses it. Multiplying an orthogonal Q by scale s multiplies every distance by |s|.', String.raw`A=sQ\implies A^TA=s^2I`),
      ], [b('Gunakan metrik Euclidean ortonormal. Similaritas invertibel memakai s ≠ 0; hanya |s| = 1 yang menjaga jarak.', 'Use an orthonormal Euclidean metric. An invertible similarity has s ≠ 0; only |s| = 1 preserves distance.')], b('det A = 1 saja tidak menjamin ortogonal: shear dapat mempunyai determinan 1 tetapi mengubah panjang.', 'det A = 1 alone does not imply orthogonality: a shear can have determinant 1 while changing lengths.'), [
        s('Periksa matriks rotasi', 'Check the rotation matrix', 'Kolom [[0,−1],[1,0]] adalah vektor satuan yang tegak lurus; RᵀR = I.', 'The columns of [[0,−1],[1,0]] are perpendicular unit vectors; RᵀR = I.', String.raw`R=\begin{pmatrix}0&-1\\1&0\end{pmatrix},\quad R^TR=I`),
        s('Putar satu titik', 'Rotate a point', '(1,0) berubah menjadi (0,1). Keduanya berjarak satu dari asal.', '(1,0) becomes (0,1). Both are one unit from the origin.', String.raw`R(1,0)=(0,1),\quad |(0,1)|=1`),
      ], b('Apakah refleksi juga menjaga jarak?', 'Does a reflection also preserve distances?'), b('Ya. Refleksi ortogonal dengan determinan −1 menjaga jarak dan sudut, tetapi membalik orientasi.', 'Yes. An orthogonal reflection with determinant −1 preserves distances and angles but reverses orientation.')),
    ],
  ],
  algebra: [
    [
      l('group', b('Mengapa sebuah operasi harus memenuhi empat syarat grup?', 'Why must an operation satisfy the four group conditions?'), [
        s('Pastikan hasil tidak keluar', 'Keep the result inside', 'Grup terdiri dari himpunan dan satu operasi. Tertutup berarti setiap a*b masih anggota himpunan. Asosiatif memungkinkan pengelompokan ulang tanpa mengubah hasil.', 'A group consists of a set and one operation. Closure keeps every a*b in the set. Associativity permits regrouping without changing the result.', String.raw`a,b\in G\implies a*b\in G,\quad (a*b)*c=a*(b*c)`),
        s('Sediakan tindakan netral dan pembatal', 'Provide a neutral action and an undo', 'Identitas e tidak mengubah anggota. Invers a⁻¹ membatalkan tindakan a. Dengan ini persamaan dapat diselesaikan lewat operasi yang tetap di grup.', 'The identity e leaves an element unchanged. The inverse a⁻¹ undoes a. These let us solve equations using operations that stay in the group.', String.raw`e*a=a*e=a,\quad a^{-1}*a=a*a^{-1}=e`),
        s('Turunkan aturan pembatalan', 'Derive cancellation', 'Jika a*b = a*c, kalikan dari kiri dengan a⁻¹ lalu kelompokkan ulang. Invers dan identitas menghapus a, menghasilkan b = c.', 'If a*b = a*c, multiply on the left by a⁻¹ and regroup. The inverse and identity remove a, leaving b = c.', String.raw`a^{-1}(ab)=a^{-1}(ac)\implies b=c`),
      ], [b('Semua syarat harus berlaku untuk semua anggota. Komutatif ab = ba adalah syarat tambahan untuk grup abelian, bukan syarat semua grup.', 'All conditions must hold for all elements. Commutativity ab = ba is an additional condition for an abelian group, not for every group.')], b('Bilangan bulat dengan perkalian bukan grup: 2 tidak punya invers perkalian di Z. Bilangan bulat dengan penjumlahan adalah grup.', 'Integers under multiplication are not a group: 2 has no multiplicative inverse in Z. Integers under addition form a group.'), [
        s('Pakai sisa modulo 4', 'Use remainders modulo 4', 'Anggotanya 0,1,2,3; setelah penjumlahan ambil sisa bagi 4 sehingga hasil tetap dalam himpunan.', 'The elements are 0,1,2,3; reduce sums modulo 4 to keep the result in the set.', String.raw`1+3\equiv0\pmod4`),
        s('Cari identitas dan invers', 'Find identity and inverses', 'Identitasnya 0. Invers 1 adalah 3 karena jumlahnya 0 modulo 4; invers 2 adalah 2.', 'The identity is 0. The inverse of 1 is 3 because their sum is 0 modulo 4; 2 is its own inverse.', String.raw`-1\equiv3,\quad -2\equiv2\pmod4`),
      ], b('Apakah tabel operasi yang tertutup sudah cukup menjadi grup?', 'Is a closed operation table sufficient to be a group?'), b('Belum. Asosiativitas, identitas, dan invers setiap anggota juga harus diperiksa.', 'No. Associativity, an identity, and an inverse for every element must also be checked.')),
      l('cyclic', b('Mengapa satu anggota dapat membangun seluruh subgrup?', 'Why can one element generate an entire subgroup?'), [
        s('Ulangi tindakan yang sama', 'Repeat the same action', 'Pangkat aⁿ berarti mengulang operasi. Pangkat nol adalah identitas; pangkat negatif mengulang invers. Semua tindakan ini harus masuk subgrup yang memuat a.', 'aⁿ repeats the operation. The zeroth power is the identity; negative powers repeat the inverse. Any subgroup containing a must contain these actions.', String.raw`\langle a\rangle=\{a^n:n\in\mathbb Z\}`),
        s('Periksa penutupan dan invers', 'Check closure and inverses', 'Menggabungkan dua pangkat menjumlahkan eksponen; membalik pangkat menegasikan eksponen. Jadi himpunan semua pangkat memang subgrup.', 'Combining powers adds exponents; taking an inverse negates the exponent. Thus the set of all powers is a subgroup.', String.raw`a^ra^s=a^{r+s},\quad (a^r)^{-1}=a^{-r}`),
        s('Hitung kapan kembali', 'Count when it returns', 'Jika aᵐ pertama kali kembali ke e, pangkat setelahnya berulang tiap m langkah. Jadi orde a adalah m dan subgrupnya memiliki m anggota.', 'If aᵐ first returns to e, later powers repeat every m steps. Thus a has order m and its generated subgroup has m elements.', String.raw`\operatorname{ord}(a)=m\implies|\langle a\rangle|=m`),
      ], [b('Pada grup aditif, aⁿ dibaca sebagai na. Untuk Zₙ, orde elemen k adalah n/gcd(n,k).', 'In an additive group, aⁿ becomes na. In Zₙ, the element k has order n/gcd(n,k).')], b('Satu elemen tidak selalu menghasilkan seluruh grup. Subgrup siklik juga dapat tak hingga jika tidak pernah kembali ke identitas.', 'One element need not generate the whole group. A cyclic subgroup can also be infinite if it never returns to the identity.'), [
        s('Tambah 2 berulang', 'Keep adding 2', 'Dalam Z₆: mulai dari identitas 0, lalu 2, lalu 4, kemudian 6 ≡ 0.', 'In Z₆: start at identity 0, then 2, then 4, then 6 ≡ 0.', String.raw`0\to2\to4\to0`),
        s('Hitung anggota berbeda', 'Count distinct elements', 'Ada tiga anggota berbeda sebelum mengulang. Ini cocok dengan 6/gcd(6,2) = 3.', 'There are three distinct elements before repetition. This agrees with 6/gcd(6,2) = 3.', String.raw`\langle2\rangle=\{0,2,4\},\quad\operatorname{ord}(2)=3`),
      ], b('Apakah 2 pembangkit Z₆?', 'Does 2 generate Z₆?'), b('Tidak; 2 hanya mencapai 0,2,4. Pembangkit Z₆ harus relatif prima dengan 6, seperti 1 atau 5.', 'No; it reaches only 0,2,4. A generator of Z₆ must be coprime to 6, such as 1 or 5.')),
      l('cosets', b('Dari mana |G| = jumlah koset × |H| berasal?', 'Where does |G| = number of cosets × |H| come from?'), [
        s('Geser semua anggota H', 'Translate all of H', 'Koset kiri gH adalah seluruh anggota H dikalikan g dari kiri. Peta h ↦ gh memiliki invers perkalian g⁻¹, jadi tidak menggandakan atau menghilangkan anggota.', 'A left coset gH multiplies all members of H by g on the left. The map h ↦ gh is reversed by g⁻¹, so no elements are duplicated or lost.', String.raw`gH=\{gh:h\in H\},\quad |gH|=|H|`),
        s('Tunjukkan koset tidak bertumpang tindih', 'Show distinct cosets do not overlap', 'Jika gh₁ = kh₂, maka g = kh₂h₁⁻¹ dan gH = kH karena H tertutup. Jadi dua koset yang bertemu sebenarnya sama.', 'If gh₁ = kh₂, then g = kh₂h₁⁻¹ and gH = kH by closure of H. Thus two intersecting cosets are actually equal.', String.raw`gH\cap kH\ne\varnothing\implies gH=kH`),
        s('Hitung kelompok yang sama besar', 'Count equal-size groups', 'Setiap anggota G ada pada kosetnya sendiri gH. Koset mempartisi G menjadi kelompok yang sama besar; menghitung semuanya memberi Lagrange.', 'Every element g lies in its coset gH. Cosets partition G into equal-size groups; counting them gives Lagrange’s theorem.', String.raw`|G|=[G:H]|H|`),
      ], [b('Lagrange dalam bentuk hitungan ini memerlukan G hingga dan H subgrup. Normalitas tidak diperlukan untuk mempartisi atau menghitung koset.', 'This counting form of Lagrange requires finite G and a subgroup H. Normality is unnecessary for partitioning or counting cosets.'), b('Euler memakai grup unit modulo n: gcd(a,n)=1. Fermat memakai prima p dan a tidak habis dibagi p.', 'Euler uses the unit group modulo n: gcd(a,n)=1. Fermat uses a prime p and a not divisible by p.')], b('Jika d membagi |G|, belum tentu ada subgrup berorde d. Kebalikan Lagrange tidak berlaku untuk semua grup.', 'If d divides |G|, a subgroup of order d need not exist. The converse of Lagrange does not hold for every group.'), [
        s('Bangun koset kedua', 'Build the second coset', 'Dalam Z₆, menambahkan 1 pada H = {0,2,4} menghasilkan {1,3,5}.', 'In Z₆, adding 1 to H = {0,2,4} gives {1,3,5}.', String.raw`1+H=\{1,3,5\}`),
        s('Hitung partisi', 'Count the partition', 'Dua kelompok dengan tiga anggota menutupi enam anggota. Tidak ada anggota yang masuk dua kelompok berbeda.', 'Two groups of three cover all six elements. No element belongs to two distinct groups.', String.raw`6=2\cdot3,\quad [\mathbb Z_6:H]=2`),
      ], b('Apakah H harus normal agar Lagrange berlaku?', 'Must H be normal for Lagrange to apply?'), b('Tidak. H cukup subgrup dari grup hingga. Normalitas diperlukan nanti untuk operasi grup pada koset.', 'No. H need only be a subgroup of a finite group. Normality is needed later to define a group operation on cosets.')),
      l('kernel', b('Mengapa kernel homomorfisma otomatis menjadi subgrup normal?', 'Why is a homomorphism’s kernel automatically a normal subgroup?'), [
        s('Pertahankan operasi', 'Preserve the operation', 'Homomorfisma φ mengirim hasil operasi ke hasil operasi bayangan. Kernel terdiri dari anggota yang dikirim ke identitas e′.', 'A homomorphism φ sends an operation’s result to the operation of the images. Its kernel consists of elements sent to identity e′.', String.raw`\varphi(ab)=\varphi(a)\varphi(b),\quad K=\{a:\varphi(a)=e'\}`),
        s('Periksa selisih dua anggota kernel', 'Check a difference of kernel elements', 'Jika a,b di kernel, φ(ab⁻¹) = e′e′⁻¹ = e′. Uji subgrup memastikan kernel tertutup terhadap operasi dan invers.', 'If a,b lie in the kernel, φ(ab⁻¹) = e′e′⁻¹ = e′. The subgroup test ensures closure under the operation and inverses.', String.raw`a,b\in K\implies ab^{-1}\in K`),
        s('Ubah sudut pandang dengan konjugasi', 'Change viewpoint by conjugation', 'Untuk k di kernel dan g sembarang, φ(gkg⁻¹) = φ(g)e′φ(g)⁻¹ = e′. Jadi konjugasi tidak keluar dari kernel: itulah normalitas.', 'For k in the kernel and any g, φ(gkg⁻¹) = φ(g)e′φ(g)⁻¹ = e′. Conjugation stays in the kernel: this is normality.', String.raw`gKg^{-1}=K\quad\text{for every }g\in G`),
      ], [b('φ harus homomorfisma grup. Kernel mengambil bayangan identitas, bukan sembarang anggota target.', 'φ must be a group homomorphism. The kernel is the preimage of the identity, not any arbitrary target element.')], b('Subgrup sembarang tidak harus normal. Semua subgrup grup abelian normal karena gkg⁻¹ = k.', 'An arbitrary subgroup need not be normal. Every subgroup of an abelian group is normal since gkg⁻¹ = k.'), [
        s('Petakan ke sisa bagi 3', 'Map to remainder modulo 3', 'Sisa penjumlahan sama dengan jumlah sisa, sehingga φ(n) = [n]₃ mempertahankan operasi.', 'The remainder of a sum equals the sum of remainders, so φ(n) = [n]₃ preserves the operation.', String.raw`\varphi(a+b)=[a+b]_3=[a]_3+[b]_3`),
        s('Cari yang menjadi nol', 'Find what becomes zero', 'Bilangan yang habis dibagi 3 mempunyai sisa nol. Kernel adalah seluruh kelipatan 3.', 'Multiples of 3 have remainder zero. The kernel is the set of all multiples of 3.', String.raw`\ker\varphi=3\mathbb Z`),
      ], b('Mengapa anggota dengan bayangan sama berbeda sebesar anggota kernel?', 'Why do elements with the same image differ by a kernel element?'), b('φ(a) = φ(b) memberi φ(ab⁻¹) = e′. Dalam notasi aditif, a−b berada di kernel.', 'φ(a) = φ(b) gives φ(ab⁻¹) = e′. In additive notation, a−b lies in the kernel.')),
      l('quotient', b('Mengapa kita boleh memperlakukan satu koset sebagai satu anggota?', 'Why can we treat a whole coset as one element?'), [
        s('Gabungkan yang tidak dapat dibedakan', 'Merge indistinguishable elements', 'Dua anggota yang berbeda sebesar anggota N dianggap sama. Koset menyimpan satu kelas dari semua anggota yang ekuivalen itu.', 'Elements differing by an element of N are treated as equivalent. A coset stores one class of all those equivalent elements.', String.raw`aN=bN\iff b^{-1}a\in N`),
        s('Pastikan pilihan wakil tidak penting', 'Make representatives irrelevant', 'Kita ingin (aN)(bN) = abN. Mengganti a dan b oleh wakil lain tidak boleh mengubah hasil. Normalitas membolehkan unsur N digeser melewati b.', 'We want (aN)(bN) = abN. Replacing a and b by other representatives must not change the result. Normality lets an N element be moved past b.', String.raw`(an_1)(bn_2)=ab(b^{-1}n_1b)n_2\in abN`),
        s('Cocokkan dengan bayangan homomorfisma', 'Match the homomorphism image', 'Jika N = kernel φ, semua wakil satu koset punya bayangan sama. Peta aN ↦ φ(a) menjadi bijeksi yang mempertahankan operasi ke image φ.', 'If N = kernel φ, representatives of one coset have the same image. The map aN ↦ φ(a) is an operation-preserving bijection onto the image of φ.', String.raw`G/\ker\varphi\cong\operatorname{im}\varphi`),
      ], [b('Untuk grup faktor, N harus subgrup normal. Isomorfisma menuju image φ; menuju seluruh target hanya jika φ surjektif.', 'For a quotient group, N must be normal. The isomorphism is onto image φ; it reaches the whole target only when φ is surjective.')], b('Jumlah koset saja belum membuktikan dua grup isomorfik. Operasinya juga harus cocok.', 'Equal numbers of cosets do not prove two groups isomorphic. Their operations must also match.'), [
        s('Gabungkan menurut selisih kelipatan 3', 'Merge differences divisible by 3', 'Bilangan 1,4,7,… berada pada kelas sama karena selisihnya anggota 3Z.', 'The integers 1,4,7,… lie in one class because their differences belong to 3Z.', String.raw`1+3\mathbb Z=4+3\mathbb Z`),
        s('Operasikan kelas', 'Operate on classes', 'Ada tiga kelas. Penjumlahan kelas [1]+[2] = [0] sama dengan penjumlahan di Z₃.', 'There are three classes. Class addition [1]+[2] = [0] agrees with addition in Z₃.', String.raw`\mathbb Z/3\mathbb Z\cong\mathbb Z_3`),
      ], b('Apakah simbol G/N berarti membagi setiap anggota G dengan N?', 'Does G/N mean numerically dividing each element by N?'), b('Tidak. Anggotanya adalah kelas koset dan operasinya diwarisi dari G.', 'No. Its elements are coset classes, and its operation is inherited from G.')),
    ],
    [
      l('cycles', b('Mengapa orde permutasi adalah KPK panjang siklus?', 'Why is a permutation’s order the LCM of its cycle lengths?'), [
        s('Ikuti satu anggota', 'Follow one element', 'Siklus (1 2 3) berarti 1 menuju 2, 2 menuju 3, dan 3 kembali ke 1. Setelah tiga penerapan, semua anggota siklus kembali.', 'The cycle (1 2 3) sends 1 to 2, 2 to 3, and 3 back to 1. After three applications, every element of that cycle returns.', String.raw`1\to2\to3\to1`),
        s('Pisahkan siklus yang tidak bertemu', 'Separate disjoint cycles', 'Setiap anggota berada pada tepat satu siklus. Siklus terpisah bekerja pada anggota berbeda, jadi dapat diikuti secara independen.', 'Every element belongs to exactly one cycle. Disjoint cycles act on different elements and can be tracked independently.', String.raw`\sigma=(1\ 2\ 3)(4\ 5)`),
        s('Cari waktu kembali bersama', 'Find a common return time', 'Agar seluruh permutasi identitas, jumlah penerapan harus kelipatan setiap panjang siklus. Kelipatan positif terkecil adalah KPK.', 'For the whole permutation to become the identity, the number of applications must be divisible by each cycle length. The least positive such number is the LCM.', String.raw`\operatorname{ord}(\sigma)=\operatorname{lcm}(m_1,\ldots,m_r)`),
      ], [b('Gunakan siklus yang saling lepas. Komposisi di materi ini dibaca dari kanan ke kiri.', 'Use disjoint cycles. Composition in this material is read right to left.')], b('Jika siklus bertumpang tindih, panjangnya tidak boleh langsung diambil KPK; hitung permutasi hasil lalu uraikan menjadi siklus terpisah.', 'For overlapping cycles, do not directly take the LCM of their lengths; compute the composed permutation and then find disjoint cycles.'), [
        s('Dua jam berbeda', 'Two separate clocks', 'Siklus pertama kembali setiap 3 langkah; siklus kedua setiap 2.', 'The first cycle returns every 3 steps; the second every 2.', String.raw`3\mid k,\quad2\mid k`),
        s('Sinkronkan', 'Synchronize', 'Waktu kembali bersama pertama adalah 6, jadi orde permutasinya 6.', 'The first simultaneous return is at 6, so the permutation has order 6.', String.raw`\operatorname{lcm}(3,2)=6`),
      ], b('Setelah tiga langkah, apakah (1 2 3)(4 5) sudah identitas?', 'After three steps, is (1 2 3)(4 5) the identity?'), b('Belum. Siklus tiga sudah kembali, tetapi siklus dua masih tertukar. Keduanya baru kembali pada langkah enam.', 'No. The 3-cycle has returned, but the 2-cycle is still swapped. Both return after six steps.')),
      l('parity', b('Mengapa siklus panjang m punya tanda (−1)^(m−1)?', 'Why does a cycle of length m have sign (−1)^(m−1)?'), [
        s('Bangun siklus dari pertukaran', 'Build a cycle from swaps', 'Satu transposisi menukar dua anggota. Siklus (a₁…aₘ) dapat dibangun memakai a₁ sebagai jangkar dalam m−1 pertukaran.', 'A transposition swaps two elements. A cycle (a₁…aₘ) can be built using a₁ as an anchor in m−1 swaps.', String.raw`(a_1\cdots a_m)=(a_1a_m)\cdots(a_1a_2)`),
        s('Setiap pertukaran membalik tanda', 'Each swap flips the sign', 'Matriks permutasi satu pertukaran membalik tanda determinan. Determinan hasil komposisi mengalikan tanda, sehingga k pertukaran memberi (−1)ᵏ.', 'One swap reverses the determinant of a permutation matrix. Composition multiplies determinants, so k swaps give (−1)ᵏ.', String.raw`\operatorname{sgn}(\sigma)=(-1)^k`),
        s('Tunjukkan paritas konsisten', 'Show parity is consistent', 'Satu permutasi mempunyai satu determinan, jadi penguraian pertukarannya selalu punya paritas sama. Permutasi bertanda +1 membentuk grup alternating Aₙ.', 'A permutation has one determinant, so every transposition decomposition has the same parity. Permutations of sign +1 form the alternating group Aₙ.', String.raw`\operatorname{sgn}(\text{m-cycle})=(-1)^{m-1}`),
      ], [b('Jumlah transposisi dapat berbeda antar penguraian, tetapi genap atau ganjilnya tetap. Untuk n ≥ 2, |Aₙ| = n!/2.', 'Different decompositions may use different numbers of swaps, but parity stays fixed. For n ≥ 2, |Aₙ| = n!/2.')], b('Panjang siklus ganjil menghasilkan permutasi genap; jangan samakan paritas panjang siklus dengan paritas permutasinya.', 'An odd-length cycle is an even permutation; do not confuse cycle-length parity with permutation parity.'), [
        s('Terapkan kanan dahulu', 'Apply the right swap first', 'Pada (1 3)(1 2), 1 menuju 2, 2 menuju 3, dan 3 menuju 1.', 'In (1 3)(1 2), 1 goes to 2, 2 to 3, and 3 to 1.', String.raw`(1\ 2\ 3)=(1\ 3)(1\ 2)`),
        s('Hitung tanda', 'Count the sign', 'Dua pertukaran memberi dua pembalikan tanda; hasilnya positif, jadi permutasinya genap.', 'Two swaps flip the sign twice; the result is positive, so the permutation is even.', String.raw`\operatorname{sgn}=(-1)^2=+1`),
      ], b('Apakah siklus (1 2 3 4) genap?', 'Is the cycle (1 2 3 4) even?'), b('Tidak. Panjang 4 memakai 3 transposisi, sehingga tandanya −1 dan permutasinya ganjil.', 'No. Length 4 uses 3 transpositions, giving sign −1 and an odd permutation.')),
    ],
    [
      l('ring', b('Mengapa pembatalan perkalian dapat gagal di gelanggang?', 'Why can multiplication cancellation fail in a ring?'), [
        s('Tambahkan operasi kedua', 'Add a second operation', 'Gelanggang punya grup abelian untuk penjumlahan, perkalian asosiatif, dan distributivitas. Invers perkalian tidak diwajibkan bagi semua anggota.', 'A ring has an abelian group under addition, associative multiplication, and distributivity. Multiplicative inverses are not required for all elements.', String.raw`a(b+c)=ab+ac,\quad(a+b)c=ac+bc`),
        s('Periksa hasil kali nol', 'Check a zero product', 'Dalam bilangan real, ab = 0 memaksa salah satu faktor nol. Dalam gelanggang, dua anggota tidak nol dapat menghasilkan nol; mereka disebut pembagi nol.', 'Over the reals, ab = 0 forces a zero factor. In a ring, two nonzero elements may multiply to zero; they are zero divisors.', String.raw`a\ne0,\ b\ne0,\ ab=0`),
        s('Turunkan kebutuhan pembatalan', 'Derive cancellation’s requirement', 'Jika ab = ac, distributivitas memberi a(b−c) = 0. Baru jika a bukan pembagi nol, b−c harus nol. Daerah integral komutatif tidak mempunyai pembagi nol.', 'If ab = ac, distributivity gives a(b−c) = 0. Only when a is not a zero divisor must b−c be zero. A commutative integral domain has no zero divisors.', String.raw`a(b-c)=0\implies b=c\quad\text{if cancellation holds}`),
      ], [b('Di sini daerah integral dan lapangan memiliki 1 ≠ 0. Lapangan komutatif dan setiap anggota bukan nol memiliki invers perkalian.', 'Here integral domains and fields have 1 ≠ 0. A field is commutative and every nonzero element has a multiplicative inverse.'), b('Pada Zₙ, k adalah unit jika gcd(k,n) = 1; Zₙ adalah lapangan tepat ketika n prima.', 'In Zₙ, k is a unit if gcd(k,n) = 1; Zₙ is a field exactly when n is prime.')], b('Anggota tidak nol belum tentu dapat dibagi. Di Z₆, perkalian dengan 2 bukan tindakan yang dapat dibatalkan.', 'A nonzero element need not allow division. In Z₆, multiplying by 2 cannot always be canceled.'), [
        s('Kalikan lalu ambil sisa', 'Multiply, then reduce', '2·3 = 6, yang menjadi 0 modulo 6.', '2·3 = 6, which becomes 0 modulo 6.', String.raw`2\cdot3\equiv0\pmod6`),
        s('Periksa faktor', 'Check the factors', '2 dan 3 keduanya bukan nol, jadi Z₆ mempunyai pembagi nol dan bukan daerah integral maupun lapangan.', 'Both 2 and 3 are nonzero, so Z₆ has zero divisors and is neither an integral domain nor a field.', String.raw`2\cdot0=2\cdot3,\quad0\ne3`),
      ], b('Apakah tidak punya pembagi nol otomatis berarti lapangan?', 'Does having no zero divisors automatically mean a field?'), b('Tidak. Z adalah daerah integral tetapi 2 tidak punya invers di Z. Daerah integral hingga, dengan 1, barulah lapangan.', 'No. Z is an integral domain but 2 has no inverse in Z. A finite integral domain with 1 is a field.')),
      l('ideal', b('Mengapa subgrup aditif saja tidak cukup untuk membuat gelanggang kuosien?', 'Why is an additive subgroup insufficient for a quotient ring?'), [
        s('Tentukan kelas yang sama', 'Specify equivalent classes', 'a dan b dianggap sama jika a−b berada dalam I. Subgrup aditif cukup untuk menjumlahkan kelas, tetapi perkalian memerlukan syarat tambahan.', 'a and b are equivalent if a−b lies in I. An additive subgroup suffices for class addition, but multiplication needs another condition.', String.raw`a+I=b+I\iff a-b\in I`),
        s('Ubah wakil sebelum mengalikan', 'Change representatives before multiplying', 'Wakil lain adalah a+i dan b+j. Selisih hasil kali dari ab adalah aj+ib+ij. Ketiganya harus tetap masuk I untuk setiap a,b di R.', 'Other representatives are a+i and b+j. Their product differs from ab by aj+ib+ij. Each term must stay in I for every a,b in R.', String.raw`(a+i)(b+j)-ab=aj+ib+ij\in I`),
        s('Kenali ideal dan maksimal', 'Recognize ideals and maximality', 'Ideal dua sisi menyerap perkalian kiri dan kanan oleh anggota R. Maka perkalian kelas terdefinisi. Untuk R komutatif dengan 1, ideal proper maksimal memberi kuosien lapangan.', 'A two-sided ideal absorbs left and right multiplication by elements of R. Class multiplication is then well-defined. In a commutative ring with 1, a proper maximal ideal yields a field quotient.', String.raw`RI\subseteq I,\quad IR\subseteq I,\quad (a+I)(b+I)=ab+I`),
      ], [b('I harus ideal dua sisi untuk gelanggang yang mungkin tidak komutatif. Teorema maksimal ↔ kuosien lapangan memakai R komutatif dengan 1 dan ideal proper.', 'I must be two-sided for a possibly noncommutative ring. Maximal ↔ field quotient assumes a commutative ring with 1 and a proper ideal.')], b('Z adalah subgelanggang Q tetapi bukan ideal Q: (1/2)·1 bukan anggota Z. Kuosien perkaliannya tidak terdefinisi dengan cara biasa.', 'Z is a subring of Q but not an ideal of Q: (1/2)·1 is not in Z. Its ordinary quotient multiplication is not well-defined.'), [
        s('Bentuk dua kelas', 'Form two classes', 'Di Z₆, ideal (2) = {0,2,4}; kelas lain {1,3,5}. Semua anggota genap dianggap nol.', 'In Z₆, ideal (2) = {0,2,4}; the other class is {1,3,5}. All even elements become zero.', String.raw`\mathbb Z_6/(2)=\{[0],[1]\}`),
        s('Periksa aritmetika baru', 'Check the new arithmetic', '[1]+[1] = [0] dan [1]·[1] = [1], sama dengan Z₂. Karena Z₂ lapangan, (2) maksimal di Z₆.', '[1]+[1] = [0] and [1]·[1] = [1], matching Z₂. Since Z₂ is a field, (2) is maximal in Z₆.', String.raw`\mathbb Z_6/(2)\cong\mathbb Z_2`),
      ], b('Mengapa harus menyerap perkalian oleh semua r di R?', 'Why must I absorb multiplication by every r in R?'), b('Wakil a,b boleh berupa anggota mana pun dari R. Jika aj atau ib keluar dari I, hasil kelas bergantung pada pilihan wakil.', 'Representatives a,b can be any elements of R. If aj or ib leaves I, the product class depends on the representative choice.')),
      l('division', b('Mengapa pembagian polinom memakai derajat, dan mengapa koefisien harus berada di lapangan?', 'Why does polynomial division use degree, and why should coefficients lie in a field?'), [
        s('Batalkan suku tertinggi', 'Cancel the leading term', 'Untuk f dengan derajat m dan g berderajat n ≤ m, kalikan g dengan (a/b)x^(m−n), di mana a,b koefisien utama. Pengurangan menghilangkan suku tertinggi f.', 'For f of degree m and g of degree n ≤ m, multiply g by (a/b)x^(m−n), where a,b are leading coefficients. Subtraction removes f’s leading term.', String.raw`f_1=f-\frac abx^{m-n}g`),
        s('Ulangi sampai derajat turun', 'Repeat until the degree drops', 'Setiap langkah menurunkan derajat sisa. Karena derajat bilangan bulat tidak negatif, proses berhenti saat sisa nol atau derajatnya lebih kecil dari g.', 'Each step lowers the remainder’s degree. Since degree is a nonnegative integer, the process stops at zero or below the degree of g.', String.raw`f=qg+r,\quad r=0\text{ or }\deg r<\deg g`),
        s('Hubungkan dengan ideal dan lapangan baru', 'Connect to ideals and new fields', 'Algoritma ini menghasilkan gcd dan identitas Bézout. Di F[x], setiap ideal utama; kuosien oleh polinom irreduksibel p adalah lapangan karena setiap kelas bukan nol punya invers dari Bézout.', 'The algorithm produces gcds and Bézout identities. Every ideal in F[x] is principal; quotienting by irreducible p gives a field because Bézout supplies inverses for nonzero classes.', String.raw`ap+bq=1\implies [b][q]=[1]\text{ in }F[x]/(p)`),
      ], [b('g ≠ 0 dan koefisien di lapangan F; lebih umum, koefisien utama g harus unit. Irreduksibel selalu relatif terhadap lapangan yang dinyatakan.', 'g ≠ 0 and coefficients lie in a field F; more generally, g’s leading coefficient must be a unit. Irreducibility is always relative to a specified field.')], b('Tanpa akar cukup untuk membuktikan irreduksibel hanya pada derajat 2 atau 3. Polinom derajat 4 dapat pecah menjadi dua kuadrat tanpa akar di F.', 'No roots proves irreducibility only in degrees 2 or 3. A degree-4 polynomial can factor into two quadratics without roots in F.'), [
        s('Bangun hasil bagi', 'Build the quotient', 'Pembagian x³+1 oleh x+1 memberi suku hasil bagi x², −x, lalu 1, dengan sisa nol.', 'Dividing x³+1 by x+1 produces quotient terms x², −x, and 1, with zero remainder.', String.raw`x^3+1=(x+1)(x^2-x+1)`),
        s('Ubah koefisien modulo 5', 'Reduce coefficients modulo 5', 'Di F₅, −1 sama dengan 4. Mengubah koefisien tidak mengubah identitas dalam lapangan itu.', 'In F₅, −1 equals 4. Reducing coefficients preserves the identity in that field.', String.raw`x^3+1=(x+1)(x^2+4x+1)\quad\text{in }\mathbb F_5[x]`),
      ], b('Apakah x²−2 irreduksibel pada semua lapangan?', 'Is x²−2 irreducible over every field?'), b('Tidak. Irreduksibel atas Q, tetapi atas R menjadi (x−√2)(x+√2). Lapangan koefisien harus selalu disebut.', 'No. It is irreducible over Q, but over R it equals (x−√2)(x+√2). Always specify the coefficient field.')),
      l('eisenstein', b('Mengapa syarat Eisenstein menghalangi faktorisasi?', 'Why do Eisenstein’s conditions prevent factorization?'), [
        s('Pindahkan soal ke koefisien bulat', 'Move to integer coefficients', 'Untuk polinom primitif berkoefisien bulat, lemma Gauss memastikan faktorisasi atas Q akan menghasilkan faktorisasi atas Z. Jadi cukup menolak faktor bulat berderajat positif.', 'For a primitive integer polynomial, Gauss’s lemma makes a factorization over Q imply one over Z. It suffices to rule out positive-degree integer factors.', String.raw`f\in\mathbb Z[x]\text{ primitive},\quad f=gh\text{ over }\mathbb Q\Rightarrow f=GH\text{ over }\mathbb Z`),
        s('Reduksi modulo p', 'Reduce modulo p', 'Jika p membagi semua koefisien selain koefisien utama, f menjadi satu monomial aₙxⁿ modulo p. Faktor-faktornya di Fₚ[x] harus berbentuk monomial juga.', 'If p divides every nonleading coefficient, f reduces to one monomial aₙxⁿ modulo p. Its factors in Fₚ[x] must also be monomials.', String.raw`\bar f=\bar a_nx^n`),
        s('Lihat konstanta dua faktor', 'Examine both constant terms', 'Karena p tidak membagi koefisien utama, derajat faktor tidak turun saat reduksi. Dua faktor berderajat positif lalu punya konstanta habis dibagi p; hasil kali konstanta habis dibagi p². Ini bertentangan dengan syarat terakhir.', 'Since p does not divide the leading coefficient, factor degrees survive reduction. Both positive-degree factors then have constants divisible by p, so their product is divisible by p², contradicting the last condition.', String.raw`p\mid G(0),\ p\mid H(0)\implies p^2\mid f(0)`),
      ], [b('p harus prima; p tidak membagi koefisien utama, p membagi semua koefisien lain termasuk koefisien nol, dan p² tidak membagi konstanta.', 'p must be prime; it does not divide the leading coefficient, divides every other coefficient including zero coefficients, and p² does not divide the constant.'), b('Kesimpulannya irreduksibel atas Q. Eisenstein adalah syarat cukup, bukan syarat perlu.', 'The conclusion is irreducibility over Q. Eisenstein is sufficient, not necessary.')], b('Jika tidak ada prima yang memenuhi syarat, hasilnya belum diketahui. Itu bukan bukti polinom dapat difaktorkan.', 'If no prime satisfies the conditions, the test is inconclusive. That does not prove the polynomial factors.'), [
        s('Pilih p = 3', 'Choose p = 3', 'Untuk x³+0x²+6x+3, koefisien utama 1 tidak habis dibagi 3; 0,6,3 semuanya habis dibagi 3.', 'For x³+0x²+6x+3, the leading coefficient 1 is not divisible by 3; 0,6,3 all are.', String.raw`3\nmid1,\quad3\mid0,6,3`),
        s('Periksa kuadrat prima', 'Check the prime’s square', '9 tidak membagi konstanta 3. Semua syarat terpenuhi, sehingga tidak ada faktorisasi berderajat positif atas Q.', '9 does not divide the constant 3. All conditions hold, ruling out a factorization into positive-degree polynomials over Q.', String.raw`9\nmid3\implies x^3+6x+3\text{ irreducible over }\mathbb Q`),
      ], b('Jika konstanta diubah dari 3 menjadi 9, apakah uji p = 3 masih berhasil?', 'If the constant changes from 3 to 9, does the p = 3 test still work?'), b('Tidak. Syarat p² tidak membagi konstanta gagal. Uji ini menjadi tidak menentukan; perlu cara lain.', 'No. The condition that p² does not divide the constant fails. This test becomes inconclusive; another method is needed.')),
    ],
  ],
}

SUMMARY_LESSONS.algebra = extendAlgebra(SUMMARY_LESSONS.algebra, SLIDE_LESSONS)

SUMMARY_LESSONS.geometry = extendGeometry(SUMMARY_LESSONS.geometry, GEOMETRY_LESSONS)

SUMMARY_LESSONS.complex = extendComplex(SUMMARY_LESSONS.complex, COMPLEX_LESSONS)
